var documenterSearchIndex = {"docs":
[{"title":"Multi-Objective Optimization","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Multi-Objective-Optimization","category":"section","text":"Multi-objective optimization balances competing objectives, typically the accuracy of an expression against its simplicity, or several performance criteria, as demonstrated in [1]. In GeneExpressionProgramming.jl a custom loss sets one fitness entry per objective, and parents are selected by NSGA-II (Non-dominated Sorting Genetic Algorithm II) [2]. The non-dominated models among the returned ones form an approximation of the Pareto front, from which you choose the trade-off you need."},{"title":"Complete Multi-Objective Example","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Complete-Multi-Objective-Example","category":"section","text":"The two objectives are the training MSE and the size of the model, measured as the length of its karva string.\n\nusing GeneExpressionProgramming\nusing Random\nusing Statistics\nusing Plots\n\n# Set random seed for reproducibility\nRandom.seed!(123)\n\n# Problem setup\nnumber_features = 2\nn_samples = 300\nnoise_level = 0.1\n\n# Features in [-2, 2], one row per sample\nx_data = 4 * (rand(Float64, n_samples, number_features) .- 0.5)\n\n# Target with several terms\ny_data = @. x_data[:,1]^3 - 2*x_data[:,1]^2*x_data[:,2] + \n            x_data[:,1]*x_data[:,2]^2 + 0.5*sin(x_data[:,1]) - \n            0.3*cos(x_data[:,2]) + x_data[:,1] + x_data[:,2]\ny_data += noise_level * randn(n_samples)\n\n# The search sees only the training part; the validation part is held out\nx_train, y_train, x_val, y_val = train_test_split(x_data, y_data; train_ratio=0.8)\n\n# Evolution parameters\nepochs = 1000\npopulation_size = 1000\n\n# Two objectives; the connectors are those of the default set that are also entered here\nregressor = GepRegressor(number_features; number_of_objectives=2,\n                         entered_non_terminals=[:+, :*, :-, :sin, :cos])\n\n# The loss runs inside the threaded fitness loop: one evaluation context per thread,\n# built once for the training data\ntrain_ctxs = thread_contexts(regressor.toolbox_, x_train')\n\nfunction multi_objective_loss(elem, validate::Bool)\n    if isnan(mean(elem.fitness)) || validate\n        y_pred = try\n            elem(train_ctxs[Threads.threadid()])\n        catch\n            nothing\n        end\n        if y_pred isa AbstractVector && all(isfinite, y_pred)\n            mse = mean(abs2, y_train .- y_pred)              # objective 1: training MSE\n            model_size = 0.01 * length(elem.expression_raw)  # objective 2: size, scaled\n            elem.fitness = (mse, model_size)\n        else\n            elem.fitness = (Inf, Inf)                        # cannot be evaluated\n        end\n    end\nend\n\ntraining_time = @elapsed fit!(regressor, epochs, population_size, multi_objective_loss; hof=20)\nprintln(\"Training completed in $(round(training_time, digits=2)) seconds\")\n\n# best_models_ holds the `hof` models ranked by the mean of their objectives; the\n# non-dominated ones among them approximate the Pareto front\nmodels = regressor.best_models_\npareto_solutions = [m for m in models if !any(o -> dominates_(o.fitness, m.fitness), models)]\nsort!(pareto_solutions, by=m -> length(m.expression_raw))\n\nr2 = get_loss_function(\"r2_score\")\nmse(m, x, y) = mean(abs2, y .- m(x'))    # recomputed: a duplicate's fitness carries the penalty\nprintln(\"Size | Training MSE | Validation MSE | Expression\")\nfor m in pareto_solutions\n    println(lpad(length(m.expression_raw), 4), \" | \",\n            lpad(round(mse(m, x_train, y_train), sigdigits=4), 12), \" | \",\n            lpad(round(mse(m, x_val, y_val), sigdigits=4), 14), \" | \", m)\nend\n\n# Three solutions: the simplest, the most accurate on the training data, and one between\nn = length(pareto_solutions)\nselected = [(pareto_solutions[1], \"Simplest\"),\n            (pareto_solutions[cld(n, 2)], \"Balanced\"),\n            (pareto_solutions[n], \"Most Accurate\")]\n\nfor (m, label) in selected\n    val_pred = m(x_val')\n    println(\"$label: $m\")\n    println(\"  Validation R²: $(round(r2(y_val, val_pred), digits=4))\")\nend\n\n# Pareto front: size against training MSE\nsizes = [length(m.expression_raw) for m in pareto_solutions]\nmses = [mse(m, x_train, y_train) for m in pareto_solutions]\np1 = scatter(sizes, mses,\n             xlabel=\"Size (symbols in the karva string)\",\n             ylabel=\"Training MSE\",\n             title=\"Pareto Front\",\n             legend=false)\n\n# Predictions of the selected solutions on the validation data\np2 = plot(layout=(1, 3), size=(1200, 300))\nfor (i, (m, label)) in enumerate(selected)\n    scatter!(p2[i], y_val, m(x_val'),\n             xlabel=\"Actual Values\", ylabel=\"Predicted Values\",\n             title=label, legend=false, alpha=0.6)\n    plot!(p2[i], [minimum(y_val), maximum(y_val)], [minimum(y_val), maximum(y_val)],\n          color=:red, linestyle=:dash)\nend\n\nsavefig(p1, \"pareto_front.png\")\nsavefig(p2, \"solution_comparison.png\")"},{"title":"Understanding the Results","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Understanding-the-Results","category":"section","text":""},{"title":"Pareto Front Analysis","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Pareto-Front-Analysis","category":"section","text":"A solution dominates another if it is no worse in every objective and better in at least one; the Pareto front is the set of solutions that no other dominates. Each point on it is a different trade-off between accuracy and size. In the plot, simple but less accurate expressions lie to the upper left and larger, more accurate ones to the lower right; the knee of the front often marks a good trade-off. Choose among the models by their validation error and by how much structure you can interpret."},{"title":"Ranking by the Mean","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Ranking-by-the-Mean","category":"section","text":"NSGA-II selects the parents by Pareto rank and crowding distance, but survival and best_models_ rank the population by the mean of each fitness tuple. That is why the example scales the size by 0.01, as examples/Main_min_example_mo.jl does: with objectives on very different scales, the larger one would dominate which models survive. The front above is taken from the hof best models only; raise hof to see more of it."},{"title":"Advanced Multi-Objective Techniques","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Advanced-Multi-Objective-Techniques","category":"section","text":"Set number_of_objectives to the length of the tuple the loss sets. The snippets below reuse the data of the example."},{"title":"Three Objectives","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Three-Objectives","category":"section","text":"regressor3 = GepRegressor(number_features; number_of_objectives=3,\n                          entered_non_terminals=[:+, :*, :-, :sin, :cos])\nctxs3 = thread_contexts(regressor3.toolbox_, x_train')\n\nfunction three_objective_loss(elem, validate::Bool)\n    if isnan(mean(elem.fitness)) || validate\n        y_pred = try\n            elem(ctxs3[Threads.threadid()])\n        catch\n            nothing\n        end\n        if y_pred isa AbstractVector && all(isfinite, y_pred)\n            residuals = abs.(y_train .- y_pred)\n            elem.fitness = (mean(abs2, residuals),                 # training MSE\n                            maximum(residuals),                    # worst-case error\n                            0.01 * length(elem.expression_raw))    # size\n        else\n            elem.fitness = (Inf, Inf, Inf)\n        end\n    end\nend\n\nfit!(regressor3, epochs, population_size, three_objective_loss)"},{"title":"Weighted Objectives","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Weighted-Objectives","category":"section","text":"Several criteria can also be folded into one objective, with weights and scales of your choice; the selection is then by tournament.\n\nregressor_ws = GepRegressor(number_features; entered_non_terminals=[:+, :*, :-, :sin, :cos])\nctxs_ws = thread_contexts(regressor_ws.toolbox_, x_train')\n\nmse_scale = var(y_train)    # your scales\nsize_scale = 50.0\n\nfunction weighted_loss(elem, validate::Bool)\n    if isnan(mean(elem.fitness)) || validate\n        y_pred = try\n            elem(ctxs_ws[Threads.threadid()])\n        catch\n            nothing\n        end\n        if y_pred isa AbstractVector && all(isfinite, y_pred)\n            mse = mean(abs2, y_train .- y_pred)\n            model_size = length(elem.expression_raw)\n            elem.fitness = (0.7 * mse / mse_scale + 0.3 * model_size / size_scale,)\n        else\n            elem.fitness = (Inf,)\n        end\n    end\nend\n\nfit!(regressor_ws, epochs, population_size, weighted_loss)"},{"title":"Constraint Handling","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Constraint-Handling","category":"section","text":"A hard constraint gives every violating model the worst fitness:\n\nfunction constrained_loss(elem, validate::Bool)\n    if isnan(mean(elem.fitness)) || validate\n        # at most 25 symbols in the karva string\n        if length(elem.expression_raw) > 25\n            elem.fitness = (Inf, Inf)\n            return\n        end\n        y_pred = try\n            elem(train_ctxs[Threads.threadid()])\n        catch\n            nothing\n        end\n        elem.fitness = y_pred isa AbstractVector && all(isfinite, y_pred) ?\n                       (mean(abs2, y_train .- y_pred), 0.01 * length(elem.expression_raw)) :\n                       (Inf, Inf)\n    end\nend\n\nfit!(regressor, epochs, population_size, constrained_loss)\n\nInf is a safe penalty: NSGA-II ranks a tuple with more non-finite entries behind one with fewer, and tournament selection (one objective) leaves non-finite fitness values out."},{"title":"Several Expressions and an Expensive Loss","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Several-Expressions-and-an-Expensive-Loss","category":"section","text":"One chromosome can carry several expressions: split_karva(elem, k) splits its genes into k parts (the gene count must be divisible by k), split_predict(elem, ctx, k) evaluates them in a buffer context, and split_equations(elem, k) prints them. A natural objective is then one per expression, e.g. for the right-hand sides of a system of ODEs, the error of each state. Where the loss is a solver in the loop, a SurrogateScreening lets it score only a few individuals per epoch and predicts the others with one Gaussian process per objective:\n\nregressor_sys = GepRegressor(2; entered_features=[:x, :y], entered_non_terminals=[:+, :-, :*],\n                             gene_count=4, head_len=4, number_of_objectives=2)\n\nfunction system_loss(elem, validate::Bool)\n    if isnan(mean(elem.fitness)) || validate\n        # your solver: it evaluates both expressions at every stage, with\n        # split_predict(elem, ctx, 2) in this thread's context, and returns one error per state\n        elem.fitness = simulate(elem)\n    end\nend\n\nsurrogate = SurrogateScreening(regressor_sys, probes;   # probes: states the solver visits\n    expressions=2,                  # one latent block per expression\n    objective_expressions=[1, 2],   # the process of objective j sees expression j alone\n    individuals_per_epoch=0.15)     # 15 % of the new individuals of an epoch\nfit!(regressor_sys, epochs, population_size, system_loss; surrogate=surrogate, hof=10)\n\nbest = regressor_sys.best_models_                 # all of them scored by the loss\nfront = best[calculate_fronts([m.fitness for m in best])[1]]\n[split_equations(m, 2) for m in front]\n\nA prediction is clamped behind the best scored value of every objective, and since the population survives by the mean of its objectives, the scored individuals that hold these values are kept among the survivors, so the best scored value of an objective never gets worse. examples/Main_surrogate_multi_objective.jl runs such a search for the Lotka–Volterra system; with its seed the screened search found both equations after 1,196 solver calls, the unscreened one after 10,168. Surrogate Screening walks through it, and the API Reference lists the options."},{"title":"Performance Considerations","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Performance-Considerations","category":"section","text":""},{"title":"Evaluating Inside the Loss","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Evaluating-Inside-the-Loss","category":"section","text":"The loss runs inside the threaded fitness loop. Calling elem(x_train') would build an evaluation context for every call; the example builds one context per thread once and evaluates in the calling thread's. The result lives in the context's buffers, so use it (or copy it) before the next evaluation in the same context."},{"title":"Initial Population","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Initial-Population","category":"section","text":"The custom-loss method of fit! has no population_sampling_multiplier keyword and uses runGep's default of 100: the initial population is picked from 100 × population_size random chromosomes, which lengthens the start of a run."},{"title":"Convergence Monitoring","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#Convergence-Monitoring","category":"section","text":"The history records, per generation, the objectives of the model ranked first by their mean:\n\nhistory = regressor.fitness_history_.train_loss\nrecorded = [history[i] for i in eachindex(history) if isassigned(history, i)]\n\np1 = plot([h[1] for h in recorded], xlabel=\"Generation\", ylabel=\"Training MSE\",\n          title=\"Objective 1\", legend=false)\np2 = plot([h[2] for h in recorded], xlabel=\"Generation\", ylabel=\"Size × 0.01\",\n          title=\"Objective 2\", legend=false)\nplot(p1, p2, layout=(1, 2))"},{"title":"References","page":"Multi-Objective Optimization","location":"examples/multi-objective.html#References","category":"section","text":"[1] Waschkowski, F., Zhao, Y., Sandberg R. D., Klewicki J., (2022), Multi-objective CFD-driven development of coupled turbulence closure models. Journal of Computational Physics, vol. 452, \n\n[2] K. Deb, A. Pratap, S. Agarwal and T. Meyarivan, (2002) \"A fast and elitist multiobjective genetic algorithm: NSGA-II,\" in IEEE Transactions on Evolutionary Computation, vol. 6, no. 2, pp. 182-197 \n\n\n\nNext: Physical Dimensionality"},{"title":"Basic Symbolic Regression","page":"Basic Regression","location":"examples/basic-regression.html#Basic-Symbolic-Regression","category":"section","text":"This example runs the complete workflow on synthetic data, from data generation to the analysis of the result."},{"title":"Problem Setup","page":"Basic Regression","location":"examples/basic-regression.html#Problem-Setup","category":"section","text":"The data comes from a known function, so the result can be compared with the truth:\n\nf(x₁, x₂) = x₁² + x₁ × x₂ - 2 × x₂²\n\nIt combines two quadratic terms and an interaction term between the variables."},{"title":"Complete Example Code","page":"Basic Regression","location":"examples/basic-regression.html#Complete-Example-Code","category":"section","text":"using GeneExpressionProgramming\nusing Random\nusing Plots\n\n# Set random seed for reproducibility\nRandom.seed!(42)\n\n# Problem parameters\nnumber_features = 2\nn_samples = 200\nnoise_level = 0.05\n\n# Training data, one row per sample\nx_train = randn(Float64, n_samples, number_features)\ny_train = @. x_train[:,1]^2 + x_train[:,1] * x_train[:,2] - 2 * x_train[:,2]^2\ny_train += noise_level * randn(n_samples)\n\n# Separate test data\nn_test = 50\nx_test = randn(Float64, n_test, number_features)\ny_test = @. x_test[:,1]^2 + x_test[:,1] * x_test[:,2] - 2 * x_test[:,2]^2\ny_test += noise_level * randn(n_test)\n\n# Evolution parameters\nepochs = 1000\npopulation_size = 1000\n\n# Create the regressor and train it\nregressor = GepRegressor(number_features)\n\ntraining_time = @elapsed fit!(regressor, epochs, population_size, x_train', y_train; loss_fun=\"mse\")\nprintln(\"Training completed in $(round(training_time, digits=2)) seconds\")\n\n# Make predictions\ntrain_predictions = regressor(x_train')\ntest_predictions = regressor(x_test')\n\n# Performance metrics, with the package's losses and scores\nfunction calculate_metrics(y_true, y_pred)\n    return (mse=get_loss_function(\"mse\")(y_true, y_pred),\n            mae=get_loss_function(\"mae\")(y_true, y_pred),\n            rmse=get_loss_function(\"rmse\")(y_true, y_pred),\n            r2=get_loss_function(\"r2_score\")(y_true, y_pred))\nend\n\ntrain_metrics = calculate_metrics(y_train, train_predictions)\ntest_metrics = calculate_metrics(y_test, test_predictions)\n\nprintln(\"Best evolved expression: \", regressor.best_models_[1])\nprintln(\"Training: \", train_metrics)\nprintln(\"Test:     \", test_metrics)\n\n# Loss of the best model per epoch (epochs after an early stop would be unassigned)\nhistory = regressor.fitness_history_.train_loss\nfitness_history = [history[i][1] for i in eachindex(history) if isassigned(history, i)]\n\nplot(fitness_history,\n     xlabel=\"Generation\",\n     ylabel=\"Best Fitness (MSE)\",\n     title=\"Evolution Progress\",\n     legend=false,\n     yscale=:log10)\nsavefig(\"fitness_evolution.png\")\n\n# Prediction accuracy plots\nmin_val = min(minimum(y_train), minimum(train_predictions))\nmax_val = max(maximum(y_train), maximum(train_predictions))\n\np1 = scatter(y_train, train_predictions,\n             xlabel=\"Actual Values\", ylabel=\"Predicted Values\",\n             title=\"Training Set\", alpha=0.6, label=\"Training Data\")\nplot!(p1, [min_val, max_val], [min_val, max_val],\n      color=:red, linestyle=:dash, label=\"Perfect Prediction\")\n\np2 = scatter(y_test, test_predictions,\n             xlabel=\"Actual Values\", ylabel=\"Predicted Values\",\n             title=\"Test Set\", alpha=0.6, color=:green, label=\"Test Data\")\nplot!(p2, [min_val, max_val], [min_val, max_val],\n      color=:red, linestyle=:dash, label=\"Perfect Prediction\")\n\nplot(p1, p2, layout=(1,2), size=(800, 300))\nsavefig(\"prediction_accuracy.png\")\n\n# Residual analysis\np3 = scatter(train_predictions, y_train .- train_predictions,\n             xlabel=\"Predicted Values\", ylabel=\"Residuals\",\n             title=\"Training Residuals\", alpha=0.6, label=\"Training\")\nhline!(p3, [0], color=:red, linestyle=:dash, label=\"Zero Line\")\n\np4 = scatter(test_predictions, y_test .- test_predictions,\n             xlabel=\"Predicted Values\", ylabel=\"Residuals\",\n             title=\"Test Residuals\", alpha=0.6, color=:green, label=\"Test\")\nhline!(p4, [0], color=:red, linestyle=:dash, label=\"Zero Line\")\n\nplot(p3, p4, layout=(1,2), size=(800, 300))\nsavefig(\"residual_analysis.png\")"},{"title":"Code Explanation","page":"Basic Regression","location":"examples/basic-regression.html#Code-Explanation","category":"section","text":""},{"title":"Regressor Configuration","page":"Basic Regression","location":"examples/basic-regression.html#Regressor-Configuration","category":"section","text":"regressor = GepRegressor(number_features)\n\nThe GepRegressor is initialized with the number of input features. Its defaults are:\n\nGene count: 3\nHead length: 6\nFunction set: +, -, *, / (also the connectors)\nConstants: 0.0 and 0.5, plus one random constant drawn from [0, 1)\n\nThe population size is not a property of the regressor; it is passed to fit!."},{"title":"Training Process","page":"Basic Regression","location":"examples/basic-regression.html#Training-Process","category":"section","text":"fit!(regressor, epochs, population_size, x_train', y_train; loss_fun=\"mse\")\n\nepochs: Number of generations\npopulation_size: Number of individuals in each generation\nx_train': The feature matrix with one row per feature, hence the transpose\ny_train: Target values\nloss_fun: Loss function (\"mse\" for mean squared error)"},{"title":"Performance Evaluation","page":"Basic Regression","location":"examples/basic-regression.html#Performance-Evaluation","category":"section","text":"The metrics come from get_loss_function:\n\nMSE: Mean squared error, which penalizes large errors more heavily\nMAE: Mean absolute error, less sensitive to outliers\nRMSE: Root mean squared error, in the same units as the target\nR²: Coefficient of determination, the proportion of variance explained\n\nThe plots show the loss of the best model per generation, the predictions against the actual values, and the residuals against the predictions, where a pattern points to a systematic error."},{"title":"Parameter Sensitivity","page":"Basic Regression","location":"examples/basic-regression.html#Parameter-Sensitivity","category":"section","text":""},{"title":"Population Size Effects","page":"Basic Regression","location":"examples/basic-regression.html#Population-Size-Effects","category":"section","text":"# Small population (fast but limited exploration)\nregressor_small = GepRegressor(number_features)\nfit!(regressor_small, 500, 100, x_train', y_train; loss_fun=\"mse\")\n\n# Large population (thorough exploration but slower)\nregressor_large = GepRegressor(number_features)\nfit!(regressor_large, 200, 2000, x_train', y_train; loss_fun=\"mse\")"},{"title":"Function Set Customization","page":"Basic Regression","location":"examples/basic-regression.html#Function-Set-Customization","category":"section","text":"# Extended function set\nregressor_extended = GepRegressor(number_features; \n                                 entered_non_terminals=[:+, :-, :*, :/, :sin, :cos, :exp])\nfit!(regressor_extended, epochs, population_size, x_train', y_train; loss_fun=\"mse\")"},{"title":"Advanced Variations","page":"Basic Regression","location":"examples/basic-regression.html#Advanced-Variations","category":"section","text":""},{"title":"Custom Loss Function","page":"Basic Regression","location":"examples/basic-regression.html#Custom-Loss-Function","category":"section","text":"using Statistics\n\nfunction custom_loss(y_true, y_pred)\n    # Huber loss (robust to outliers)\n    delta = 1.0\n    residual = abs.(y_true .- y_pred)\n    return mean(ifelse.(residual .<= delta, \n                       0.5 * residual.^2, \n                       delta * (residual .- 0.5 * delta)))\nend\n\n# Use custom loss function\nfit!(regressor, epochs, population_size, x_train', y_train; loss_fun=custom_loss)"},{"title":"Early Stopping","page":"Basic Regression","location":"examples/basic-regression.html#Early-Stopping","category":"section","text":"Every call of fit! starts a new search, so early stopping belongs inside the run: break_condition(population, epoch) is called after every epoch with the ranked population, and the run stops when it returns true.\n\nfunction make_early_stopping(; patience=50, min_improvement=1e-6)\n    best_fitness = Inf\n    since_improvement = 0\n    return function (population, epoch)\n        current = population[1].fitness[1]\n        if current < best_fitness - min_improvement\n            best_fitness = current\n            since_improvement = 0\n        else\n            since_improvement += 1\n        end\n        return since_improvement >= patience || current < 1e-12\n    end\nend\n\nfit!(regressor, epochs, population_size, x_train', y_train; loss_fun=\"mse\",\n     break_condition=make_early_stopping(patience=50))"},{"title":"Cross-Validation","page":"Basic Regression","location":"examples/basic-regression.html#Cross-Validation","category":"section","text":"using Statistics\n\nfunction cross_validate(X, y, k_folds=5)\n    n_samples = size(X, 1)\n    fold_size = div(n_samples, k_folds)\n    scores = Float64[]\n    \n    for fold in 1:k_folds\n        # Create train/validation split\n        val_start = (fold - 1) * fold_size + 1\n        val_end = min(fold * fold_size, n_samples)\n        \n        val_indices = val_start:val_end\n        train_indices = setdiff(1:n_samples, val_indices)\n        \n        X_train_fold = X[train_indices, :]\n        y_train_fold = y[train_indices]\n        X_val_fold = X[val_indices, :]\n        y_val_fold = y[val_indices]\n        \n        # Train model\n        regressor_fold = GepRegressor(size(X, 2))\n        fit!(regressor_fold, 500, 500, X_train_fold', y_train_fold; loss_fun=\"mse\")\n        \n        # Evaluate\n        y_pred_fold = regressor_fold(X_val_fold')\n        mse_fold = mean((y_val_fold .- y_pred_fold).^2)\n        push!(scores, mse_fold)\n        \n        println(\"Fold $fold MSE: $(round(mse_fold, digits=6))\")\n    end\n    \n    println(\"Mean CV MSE: $(round(mean(scores), digits=6)) ± $(round(std(scores), digits=6))\")\n    return scores\nend\n\n# Perform cross-validation\ncv_scores = cross_validate(x_train, y_train)\n\n\n\nNext: Multi-Objective Optimization"},{"title":"API Reference","page":"API Reference","location":"api-reference.html#API-Reference","category":"section","text":"The public functions, types and modules of GeneExpressionProgramming.jl, by functionality. Everything listed is exported by GeneExpressionProgramming unless it is written with its module prefix."},{"title":"Regressors","page":"API Reference","location":"api-reference.html#Regressors","category":"section","text":""},{"title":"GepRegressor","page":"API Reference","location":"api-reference.html#GepRegressor","category":"section","text":"The regressor for scalar symbolic regression.\n\nGepRegressor(feature_amount::Int; kwargs...)\n\nParameters:\n\nfeature_amount::Int: Number of input features\nentered_features::Vector{Symbol} = Symbol[]: Feature names; x1, x2, ... when empty\nentered_non_terminals::Vector{Symbol} = [:+, :-, :*, :/]: Functions (see Function Sets)\ngene_connections::Vector{Symbol} = [:+, :-, :*, :/]: Connectors, the functions that join the genes; only those also in entered_non_terminals are used\nentered_terminal_nums::Vector{Symbol} = [Symbol(0.5), Symbol(0.0)]: Constant terminals\nrnd_count::Int = 1: Number of further constant terminals, drawn uniformly from [0, 1)\nnode_type::Type = Float64: Numeric type of the constant terminals\ngene_count::Int = 3: Number of genes per chromosome\nhead_len::Int = 6: Head length of each gene (the tail is head_len + 1 long)\ntail_weigths = [0.6, 0.2, 0.2]: Sampling weight of each feature, each fixed constant and each random constant when terminals are drawn\nhead_weigths = nothing: Accepted; not used\nnumber_of_objectives::Int = 1: Number of objectives; more than one needs the fit! method with a custom loss, and selects with NSGA-II\nconsidered_dimensions::Dict{Symbol,Vector{Float16}} = Dict(): Physical dimensions of the features and constants, keyed by their symbols (:x1, :x2, ... or the entered_features; Symbol(0.5), ... for the entered_terminal_nums); unlisted ones are dimensionless. When given, the regressor builds the library that the unit repair draws on, which fit! needs for a target_dimension\nmax_permutations_lib::Int = 10000: New library expressions kept per build round\nrounds::Int = 4: Library build rounds; library expressions have up to rounds + 1 symbols\npreamble_syms::Vector{Symbol} = Symbol[]: Terminals appended to every chromosome, one per gene, outside its expression\n\nFields:\n\nbest_models_::Vector{Chromosome}: The best models of the last fit!, best first\nfitness_history_: Training history: train_loss and val_loss, one fitness tuple per epoch\ntoolbox_::Toolbox: The GEP configuration (alphabet, operators, probabilities)\ntoken_dto_: The library and unit rules used by the repair (nothing without considered_dimensions)\n\nExample:\n\nregressor = GepRegressor(3;\n                        gene_count=3,\n                        head_len=5,\n                        entered_non_terminals=[:+, :-, :*, :/, :sin, :cos])"},{"title":"GepTensorRegressor","page":"API Reference","location":"api-reference.html#GepTensorRegressor","category":"section","text":"Regressor for models over scalars, vectors and higher-order tensors (Tensors.jl types).\n\nGepTensorRegressor(feature_amount::Int; kwargs...)\n\nParameters:\n\nfeature_amount::Int: Number of input features (scalar and tensor-valued alike)\nproblem_dimension::Int = 2: Spatial dimension of the tensors\nfeature_names::Vector{String} = String[]: Names of the features, used when printing; x1, x2, ... when empty\nentered_non_terminals::Vector{Symbol} = [:+, :-, :*, :/]: Functions, including the tensor operations (see Tensor Operations)\ngene_connections::Vector{Symbol} = [:+, :*]: Connectors; only those also in entered_non_terminals are used\nentered_terminal_nums::Vector{<:AbstractFloat} = Float64[]: Constant terminals\nrnd_count::Int = 0: Number of further constant terminals, drawn uniformly from rnd_limits = (-0.1, 0.1)\ngene_count::Int = 2: Number of genes per chromosome\nhead_len::Int = 3: Head length of each gene\nnumber_of_objectives::Int = 1: Number of objectives\nhead_tail_balance::Real = 0.6: Weight of the binary functions when head symbols are drawn; tail_weigths = [0.7, 0.2, 0.1]: as for GepRegressor\nconsidered_dimensions, max_permutations_lib = 10000, rounds = 5: As for GepRegressor, with two differences: the dimensions are keyed :x1, :x2, ... in feature order whatever feature_names says, and each carries the tensor order in front of the SI exponents; constants are dimensionless. Only the functions with tensor unit rules can be used with dimensions (see Tensor Operations)\nhigher_dim_feature_amount::Int = 0: Accepted; not used\n\nFields:\n\nbest_models_, fitness_history_, toolbox_, token_dto_: As for GepRegressor\ninput_values: The input columns, set by allocate_buffers!\nbuffers: The per-thread evaluation buffers, set by allocate_buffers!\n\nExample:\n\nregressor = GepTensorRegressor(5;\n                              problem_dimension=3,\n                              gene_count=3,\n                              head_len=4,\n                              entered_non_terminals=[:+, :-, :*],\n                              feature_names=[\"x1\", \"x2\", \"U1\", \"U2\", \"U3\"])\n# x1, x2: scalar columns; u1, u2, u3: columns of Tensor{1,3} (see Tensor Regression)\nallocate_buffers!(regressor, (x1, x2, u1, u2, u3))    # one column per feature"},{"title":"Training","page":"API Reference","location":"api-reference.html#Training","category":"section","text":""},{"title":"fit!","page":"API Reference","location":"api-reference.html#fit!","category":"section","text":"Train a regressor. There are three methods:\n\nScalar regression on data arrays:\n\nfit!(regressor::GepRegressor, epochs::Int, population_size::Int, x_train::AbstractArray,\n     y_train::AbstractArray; kwargs...)\n\nx_train holds one row per feature and one column per sample (hence the transposes in the examples). Throws an ArgumentError when a function or terminal has no batched counterpart.\n\nKeyword Arguments:\n\nx_test = nothing, y_test = nothing: Held-out data for the validation loss (the training data when not given)\nloss_fun::Union{String,Function} = \"mse\": Loss to minimise: a name (see Loss Functions) or a function (y_true, y_pred) -> Real\nloss_fun_validation::Union{String,Function} = \"mse\": Loss reported on the held-out data\nhof::Int = 3: Number of best models returned in best_models_\noptimization_epochs::Int = 100: Every this many epochs, if the best model has improved since the last time, Nelder-Mead tunes each occurrence of a constant in it on the training loss; values that lower the loss are kept in its optimised_constants. Not with linear_scaling\nmax_iterations::Int = 1000: Iterations of that constant optimisation\nlinear_scaling::Bool = false: Score each chromosome as the least-squares combination of its genes, one coefficient per gene (stored in scaling_weights), so that evolution searches for the structure only; the model is then the weighted sum of its genes. Needs :+ and :* among the functions. With a target_dimension, every gene is held to it, not only the connected expression, since the coefficients are dimensionless only then\ntarget_dimension::Union{Vector{Float16},Nothing} = nothing: Target physical dimension; only homogeneous individuals are scored, the others are repaired (needs considered_dimensions)\ncorrection_epochs::Int = 1: Run the repair every this many epochs\ncorrection_amount::Real = 1.0: The most individuals repaired per correction epoch, as a fraction of the population\ncycles::Int = 10: Repair attempts per individual\nlib_seed_amount::Real = 0.5: Fraction of the initial population seeded with library expressions of the target dimension\npenalty::AbstractFloat = 2.0: Factor on the cached fitness of a new individual whose karva string has been scored before\npopulation_sampling_multiplier::Int = 1: Above 1, the initial population is picked from this many times more random chromosomes, by the mean of their predictions on random probe data (select_n_samples_lhs). The selection is meant as Latin hypercube sampling, but its target points are not stratified\nbreak_condition = nothing: (population, epoch) -> Bool, stops the run when true\nfile_logger_callback = nothing: (population, epoch, selected_members), called every epoch\nsave_state_callback = nothing: (population, strategy), called every epoch\nload_state_callback = nothing: () -> (population, start_epoch), resumes a run\nsurrogate = nothing: A SurrogateScreening for an expensive loss: the loss scores only the individuals it picks each epoch, and the others get the prediction of a Gaussian process\nopt_method_const, n_starts, buffered: Accepted; not used\n\nCustom loss over chromosomes, for several objectives or any evaluation of your own:\n\nfit!(regressor::GepRegressor, epochs::Int, population_size::Int, loss_function::Function; kwargs...)\n\nloss_function(elem::Chromosome, validate::Bool) sets elem.fitness to a tuple with one entry per objective (as many as number_of_objectives); its return value is ignored. It is called inside the threaded fitness loop for the unscored chromosomes (fitness NaN), once per distinct karva string, and each epoch with validate = true for the best one. The loop hands the chromosomes out one at a time to whichever thread is free, so a loss whose cost varies from one chromosome to the next keeps every thread busy; a call stays on one thread and no other call shares its Threads.threadid() meanwhile, even if the loss waits (on an external solver, say). Evaluate the chromosome in a per-thread context (see thread_contexts), and catch errors – an exception thrown by the loss stops fit!.\n\nKeyword Arguments:\n\nloss_function_validation = nothing: (elem, validate) -> Tuple, called for the best chromosome each epoch; its return value is recorded as the validation loss (without it, the training fitness is recorded)\nhof, target_dimension, correction_epochs, correction_amount, cycles, lib_seed_amount, penalty, break_condition, file_logger_callback, save_state_callback, load_state_callback: As above\ngene_wise_dimension::Bool = false: Hold every gene to target_dimension rather than the connected expression, for a loss that scores the least-squares combination of the genes\nsurrogate = nothing: A SurrogateScreening: the loss is called only for the individuals it picks each epoch (and for a best or returned model that carries a prediction); the others get the prediction of a Gaussian process\nconstant_optimizer = nothing: A ScreenedNelderMead: every optimization_epochs::Int = 100 epochs, if the best model has improved since the last time, its constants are tuned against loss_function by Nelder-Mead, screened by a Gaussian process or not (optimize_constants!), within max_evaluations loss calls. The loss must evaluate the chromosome by a path that applies tuned constants: elem(ctx) or split_predict(elem, ctx, k). With a surrogate, the model tuned is the best one the loss has scored, never one that carries a prediction\noptimizer_function_, opt_method_const, max_iterations, n_starts: Accepted; not used\n\nThis method has no population_sampling_multiplier keyword; runGep's default of 100 applies, so the initial population is picked from 100 × population_size random chromosomes as described above.\n\nTensor regression:\n\nfit!(regressor::GepTensorRegressor, epochs::Int, population_size::Int, loss_function::Function; kwargs...)\n\nThe loss has the same form as in 2.; it typically evaluates with predictT. Call allocate_buffers! first. Tournaments are of 0.3 % of the population (at least 3), and duplicates take the cached fitness times 2.0 (runGep's default penalty).\n\nKeyword Arguments:\n\nhof, target_dimension, correction_epochs, correction_amount, cycles, lib_seed_amount, break_condition, file_logger_callback, save_state_callback, load_state_callback: As above\ngene_wise_dimension::Bool = false: Hold every gene to target_dimension rather than the connected expression; a loss that scores with predictT_scaled needs it unless the gene connectors are only :+ and :-\npopulation_sampling_multiplier = 1: Keep it at 1: the sampling probes candidates with the scalar evaluator, which does not accept a tensor toolbox (with a surrogate, the sampling uses its TensorEmbedder instead and works)\nsurrogate = nothing: A SurrogateScreening built with SurrogateScreening(regressor, probes), as for method 2.\nconstant_optimizer = nothing, optimization_epochs::Int = 100: As for method 2, for a loss that evaluates the chromosome with predictT(regressor, elem), which applies tuned constants\n\nExamples (x_train, y_train, x_test, y_test, target_dim and the losses as defined on this page and in the examples):\n\n# Basic regression\nfit!(regressor, 1000, 1000, x_train', y_train; loss_fun=\"mse\")\n\n# With validation data\nfit!(regressor, 1000, 1000, x_train', y_train;\n     x_test=x_test', y_test=y_test, loss_fun=\"rmse\")\n\n# With physical dimensions (a regressor built with considered_dimensions)\nfit!(regressor, 1000, 1000, x_train', y_train;\n     target_dimension=target_dim)\n\n# Custom (e.g. multi-objective or tensor) loss\nfit!(regressor, 100, 500, multi_objective_loss)"},{"title":"Prediction and Evaluation","page":"API Reference","location":"api-reference.html#Prediction-and-Evaluation","category":"section","text":""},{"title":"Calling a regressor or a chromosome","page":"API Reference","location":"api-reference.html#Calling-a-regressor-or-a-chromosome","category":"section","text":"(regressor::GepRegressor)(x_data)     # the best model's predictions\n(chromosome::Chromosome)(x_data)      # any chromosome's predictions\n(chromosome::Chromosome)(ctx)         # predictions in a prebuilt evaluation context\n\nx_data holds one row per feature and one column per sample. The predictions include the fitted constants (optimised_constants) or gene coefficients (scaling_weights) when the model has them.\n\nExample:\n\npredictions = regressor(x_test')\nsecond_best = regressor.best_models_[2](x_test')"},{"title":"thread_contexts","page":"API Reference","location":"api-reference.html#thread_contexts","category":"section","text":"thread_contexts(toolbox, x_data; std_return_type=Float64)\nbuffer_context(toolbox, x_data; std_return_type=Float64)\n\nbuffer_context builds an evaluation context for x_data (one row per feature): the input columns, the operators, and the buffers the evaluator writes into. thread_contexts builds one per thread id, for losses that run inside the threaded fitness loop. Both work for GepRegressor toolboxes only; for a tensor toolbox, whose callbacks are operator objects, buffer_context returns nothing, and a tensor loss evaluates with predictT instead.\n\nusing Statistics\n\nctxs = thread_contexts(regressor.toolbox_, x_train')\n\nfunction loss(elem, validate::Bool)\n    if isnan(mean(elem.fitness)) || validate\n        y_pred = elem(ctxs[Threads.threadid()])\n        # ... set elem.fitness from y_pred\n    end\nend\n\nThe result of elem(ctx) lives in the context's buffers; use it (or copy it) before the next evaluation in the same context."},{"title":"Tensor prediction","page":"API Reference","location":"api-reference.html#Tensor-prediction","category":"section","text":"allocate_buffers!(regressor::GepTensorRegressor, data_x; std_return_type=Float64)\npredictT(regressor::GepTensorRegressor, rek_string::Vector)\npredictT(regressor::GepTensorRegressor, chromosome::Chromosome)\npredictT(regressor::GepTensorRegressor, rek_string::Vector, x_data::Vector)\npredictT(regressor::GepTensorRegressor, rek_string::Vector, new_input_values::Dict)\npredictT_scaled(regressor::GepTensorRegressor, chromosome::Chromosome, target)\npredictT_scaled!(out, regressor::GepTensorRegressor, chromosome::Chromosome, target)\ngene_bases(regressor::GepTensorRegressor, chromosome::Chromosome)\n\nallocate_buffers! stores the input columns (data_x: one column per feature, as a tuple or Vector{Any}) and allocates the per-thread buffers for them (std_return_type is not used). Required before fit!.\npredictT(regressor, rek_string) evaluates a karva string (chromosome.expression_raw) on those columns, in the calling thread's buffers; use or copy the result before the next evaluation on the same thread.\npredictT(regressor, chromosome) does the same for a chromosome, with its tuned constants (optimised_constants) if it has them, which a loss needs for optimize_constants! and the constant_optimizer of fit! to reach it; with tuned constants, the expression runs on the allocating path of the evaluator, into fresh arrays.\npredictT(regressor, rek_string, x_data) evaluates it on new data (one column per feature, in the same order), into fresh arrays; constants are broadcast to the new sample count.\npredictT(regressor, rek_string, new_input_values) evaluates it on the stored columns, with the column of each terminal index => value in the Dict set to value in every sample.\npredictT_scaled fits one least-squares coefficient per gene against target – the tensor counterpart of linear_scaling – and returns the scaled prediction; the coefficients are stored in scaling_weights. Genes whose output does not match target in length and element type are left out; it returns nothing when no gene matches or the fit is not finite. The coefficients are dimensionless only if every gene has the target dimension (gene_wise_dimension=true in fit!). When every column and target are Vector{Float64}, the genes are evaluated by the compiled evaluator into preallocated buffers, with the same result.\npredictT_scaled! writes that prediction into out (a vector like target) and returns it; with one out per thread slot, a loss allocates no prediction per candidate (second example).\ngene_bases evaluates every gene on its own, into fresh arrays.\n\nExample (the columns as in Tensor Regression):\n\nbest = regressor.best_models_[1]\npred_train = predictT(regressor, best.expression_raw)\n# x1_new, x2_new, u1_new, u2_new, u3_new: new columns, one per feature, in the same order\npred_new = predictT(regressor, best.expression_raw, Any[x1_new, x2_new, u1_new, u2_new, u3_new])\n\nExample (a scaled loss on Vector{Float64} columns and target y, one prediction buffer per thread slot):\n\npreds = [similar(y) for _ in 1:thread_slots()]\nfunction loss(elem, validate::Bool)\n    if isnan(mean(elem.fitness)) || validate\n        pred = predictT_scaled!(preds[Threads.threadid()], regressor, elem, y)\n        if pred isa AbstractVector && allfinite(pred)\n            pred .-= y                                  # the residual, in place\n            elem.fitness = (sum(abs2, pred) / length(y),)\n        else\n            elem.fitness = (1e6,)\n        end\n    end\nend"},{"title":"Inspecting Models","page":"API Reference","location":"api-reference.html#Inspecting-Models","category":"section","text":"A model is a Chromosome. Printing it (println, string) writes it as an equation, with every binary operation parenthesised and with fitted constants or gene coefficients in place.\n\nbest = regressor.best_models_[1]\nprintln(best)                    # e.g. ((x1 * x1) + (x2 * (x1 - (x2 + x2))))\nbest.fitness                     # tuple, one entry per objective\nbest.expression_raw              # the karva string (Vector{Int8}) the evaluator runs\nbest.optimised_constants         # tuned constants, or nothing\nbest.scaling_weights             # gene coefficients (linear scaling), or nothing\nbest.dimension_homogene          # true once the model is known to meet the target dimension"},{"title":"equation_string","page":"API Reference","location":"api-reference.html#equation_string","category":"section","text":"equation_string(chromosome::Chromosome)\n\nThe string show prints: the model as an equation, with fitted constants in place, or as a weighted sum of genes when it carries gene coefficients; both rounded to 6 significant digits."},{"title":"printkarvastrings","page":"API Reference","location":"api-reference.html#print*karva*strings","category":"section","text":"print_karva_strings(chromosome::Chromosome; split_len::Int=1)\n\nThe expression as a string, built from the karva string alone – without fitted constants or gene coefficients. split_len = k > 1 skips the first k - 1 connectors and returns the partial results, last gene first, instead of one string; with k equal to the gene count that is one string per gene."},{"title":"fitness / set_fitness!","page":"API Reference","location":"api-reference.html#fitness-/-set_fitness!","category":"section","text":"fitness(chromosome::Chromosome)\nset_fitness!(chromosome::Chromosome, value::Tuple)\n\nGet or set the fitness tuple."},{"title":"Training history","page":"API Reference","location":"api-reference.html#Training-history","category":"section","text":"history = regressor.fitness_history_\ntrain = [history.train_loss[i][1] for i in eachindex(history.train_loss) if isassigned(history.train_loss, i)]\nval = [history.val_loss[i][1] for i in eachindex(history.val_loss) if isassigned(history.val_loss, i)]\n\nOne tuple per epoch, for the best model of that epoch; the epochs after a break_condition stopped the run are unassigned."},{"title":"Surrogate Screening","page":"API Reference","location":"api-reference.html#Surrogate-Screening","category":"section","text":"For an expensive loss (a solver in the loop, a simulation), a Gaussian process decides which individuals of an epoch the loss scores and predicts the loss of the others. It is the Julia counterpart of gep.SurrogateBatchStrategy of the Python package, with its defaults. The types below are exported; the functions they are built from live in the submodule GepSurrogate. The example Surrogate Screening walks through a search with one objective and one with several expressions and objectives."},{"title":"SurrogateScreening","page":"API Reference","location":"api-reference.html#SurrogateScreening","category":"section","text":"SurrogateScreening(embedder; screen=GpScreen(), individuals_per_epoch=10, kwargs...)\nSurrogateScreening(regressor::GepRegressor, probes::AbstractMatrix; embedding=:expression,\n    expressions=1, objective_expressions=nothing, kwargs...)\nSurrogateScreening(regressor::GepTensorRegressor, probes::AbstractVector; embedding=:expression,\n    expressions=1, objective_expressions=nothing, components=1, kwargs...)\n\nPass it to fit! (or runGep) as surrogate. embedder maps a chromosome to its latent vector, or to nothing for an expression that cannot be evaluated. The regressor methods build it on probes: one row per feature and one column per probe sample for a GepRegressor (like x_train), one column per feature for a GepTensorRegressor (like the data of allocate_buffers!); embedding = :genes embeds one block per gene, and expressions = k one block per expression of a chromosome that carries k of them (below). A few dozen probe samples from the relevant range suffice.\n\nEach epoch, the new individuals (one per karva string) are embedded; one that cannot be embedded is scored as a crash without a loss call. Then:\n\nWarmup, until warmup_runs individuals (six times the batch, at least 60) have a finite loss: at most warmup_batch of them (twice the batch, at least 20; nothing for all) are scored, picked uniformly (or by Latin hypercube sampling with warmup_lhs=true), and the others get the median loss of that batch.\nScreened epochs: a GpScreen is fitted on the scored individuals (the last archive_cap = 1000); the loss scores individuals_per_epoch individuals (a count, or a share in (0, 1) of the new individuals), explore_fraction = 0.1 of them picked as in the warmup, the rest by the acquisition; every other individual gets the prediction mean + impute_beta * deviation (impute_beta = 0).\nA prediction is at least one float step worse than the best loss scored so far on every objective (the incumbent), and it is never cached: a copy of a predicted individual is screened again, while a copy of a scored one takes its loss times penalty, even once the fitness cache has dropped it.\nA prediction is provisional: with rescreen = true, the default with several objectives (rescreen = nothing), the individuals that carry one are screened again at the start of every epoch, next to the new ones, so a later process can pick them for a loss call or give them a fresh prediction. The batch stays a count or a share of the new individuals. Without, a surviving prediction is never looked at again, and in a search with several objectives the population fills up with stale ones; with one objective, re-screening was a wash on the benchmark of the package.\nThe best individual of an epoch is scored if it carries a prediction, before its loss is recorded and selected with; the returned hall of fame is scored at the end (validate_hof = true).\nFrom min_failures = 5 failed loss calls (a non-finite value) on, a FeasibilityModel gates each batch towards the individuals the loss can score.\nWith budget_rule = :uncertainty, an epoch scores only the individuals whose optimistic bound still beats the incumbent, between min_individuals and individuals_per_epoch of them (measured by the Python package as a gain with several objectives and as a collapse with one). budget_decay schedules the batch from warmup_batch down to individuals_per_epoch.\nAn epoch breeds offspring_multiplier times the children the population takes (by default 3 from 10 individuals per epoch on, read on a hundred individual epoch, and 1 below), and the process picks which enter (GepSurrogate.preselect).\nAn oversampled initial population (population_sampling_multiplier > 1) is picked by Latin hypercube sampling over the latent vectors (characterize_initial = true).\ntarget_transform = :log10 brings the losses into the space the processes work in; use :asinh or :none for objectives that can be negative.\n\nSeveral objectives and several expressions. A loss that sets several objectives (number_of_objectives = k) is screened with one process per objective. The pick scalarizes them by a random augmented Chebyshev weighting per epoch (ParEGO), or ranks by the expected hypervolume improvement (GpScreen(acquisition = :ehvi)). A prediction is clamped behind the best scored value of every objective, so no prediction dominates the individual holding one; and since the population survives by its mean fitness, which a prediction can beat without dominating anyone, the scored individuals that hold the best value of an objective are kept right behind the leader, where the next generation does not replace them (GepSurrogate.keep_best_scored!). The best scored value of every objective among the survivors thus never gets worse. An objective the loss computes from the chromosome alone, e.g. a size, is better computed than predicted: exact_objectives = Dict(2 => c -> 0.01 * length(c.expression_raw)) gives every predicted individual that value (without a clamp), and the acquisition sees it without uncertainty. The function has to return exactly the value the loss sets. A chromosome that carries several expressions, split by split_karva in the loss (split_predict evaluates them), is embedded with one block per expression: SurrogateScreening(regressor, probes; expressions = 2), which needs a gene count divisible by the number of expressions. The whole karva string joins the parts with connectors the loss never uses, so its behaviour is not what the loss sees. Where each objective judges one expression, objective_expressions = [1, 2] (one entry per objective, 0 or :all for one that depends on all of them) lets the process of an objective see the latent block of its expression alone (it sets the inputs of the GpScreen, GepSurrogate.expression_blocks). The result of such a search is a front: take the non-dominated members of best_models_ (calculate_fronts), which the loss has all scored (validate_hof); a large hof costs a loss call per predicted member at the end.\n\nDiagnostics: evaluated_count (loss calls made through the screening), imputed_count (predictions), broken_count, failed_count, spearman_log (rank correlation of prediction and loss per screened batch, of the first predicted objective with several), spearman_objectives (the same, one log per objective), last_batch (the individuals scored in the last epoch, as (chromosome, fitness, reason), the reason being :warmup, :acquisition, :explore or :validation), archive_size(s), is_validated(s, chromosome) (the individual carries a loss, not a prediction).\n\nusing Random\n\nregressor = GepRegressor(2; number_of_objectives=1)\nprobes = x_train[:, randperm(size(x_train, 2))[1:36]]     # x_train: one row per feature\nsurrogate = SurrogateScreening(regressor, probes; individuals_per_epoch=0.15, seed=1)\nfit!(regressor, 100, 500, expensive_loss; surrogate=surrogate)\n\n@show surrogate.evaluated_count surrogate.imputed_count\n@show all(is_validated(surrogate, m) for m in regressor.best_models_)   # true"},{"title":"GpScreen","page":"API Reference","location":"api-reference.html#GpScreen","category":"section","text":"GpScreen(; acquisition=:lcb, kappa=1.0, rho=0.05, scalarize_per_pick=false, fit=false, nugget=1e-6,\n    inputs=nothing)\n\nRanks the pending individuals with a Gaussian process per objective. acquisition is :lcb (the optimistic bound mean - kappa * deviation, the default the Python study measured best), :logei (the top of the log expected improvement), :logei_believer (greedy LogEI with the kriging believer between the picks) or :ehvi (expected hypervolume improvement, several objectives). With several objectives the other acquisitions pick by a random augmented Chebyshev scalarization (weight rho), drawn per fit or, with scalarize_per_pick, per pick. fit = true chooses the length scale and noise of the processes by the marginal likelihood over a grid. inputs gives the latent coordinates the process of each objective sees (one range or index vector per objective, nothing for all); with it, :lcb scalarizes the bounds of the processes of the objectives by the weights of the epoch. A custom screen is any object with methods of GepSurrogate.fit_screen!, predict_screen, select_screen and plausible_screen."},{"title":"GaussianProcess and FeasibilityModel","page":"API Reference","location":"api-reference.html#GaussianProcess-and-FeasibilityModel","category":"section","text":"GaussianProcess(X, y; nugget=1e-6, fit=false)      # X: d × n, one latent vector per column\nFeasibilityModel(X, labels; prior=2.0, bandwidth=0.25)\n\nExact Gaussian process regression with a radial basis kernel whose length scale is the median pairwise distance (or fitted, with fit = true); GepSurrogate.posterior(gp, Xq) gives the standardized mean and deviation, unstandardize, expected_improvement, log_expected_improvement and believe build on it. FeasibilityModel is a kernel-weighted average of the outcomes (1 for a finite loss, 0 for a failure), pulled to the overall rate by prior pseudo observations; call it on a d × m matrix for m probabilities."},{"title":"SemanticEmbedder, GeneEmbedder, TensorEmbedder","page":"API Reference","location":"api-reference.html#SemanticEmbedder,-GeneEmbedder,-TensorEmbedder","category":"section","text":"SemanticEmbedder(toolbox, probes::AbstractMatrix; transform=:asinh, expressions=1)\nGeneEmbedder(toolbox, probes::AbstractMatrix; transform=:asinh, count=nothing)\nTensorEmbedder(toolbox, probes::AbstractVector; components=1, transform=:asinh, per_gene=false,\n    expressions=1)\n\nMap a chromosome to the transformed outputs of its expression on the probe set (SemanticEmbedder), of its genes one block each (GeneEmbedder), or of a tensor expression flattened to components numbers per sample (TensorEmbedder), or to nothing if an output is not finite. With expressions = k, the chromosome is split into its k expressions (split_karva) and embedded with one block per expression; for a TensorEmbedder, components is then one number for all of them or a vector with one per expression. Constants tuned by an optimiser and gene coefficients are not applied, as an individual is embedded before it is scored."},{"title":"Constants Against an Expensive Loss","page":"API Reference","location":"api-reference.html#Constants-Against-an-Expensive-Loss","category":"section","text":"The constants of a model, tuned against an expensive custom loss (a solver in the loop, a CFD simulation) by Nelder-Mead, plain or screened by a Gaussian process over the constants. The functions they are built from live in the submodule GepSimplex. Coefficient Tuning shows when to use which variant, with measurements, and walks through both uses, inside a search and on their own."},{"title":"ScreenedNelderMead","page":"API Reference","location":"api-reference.html#ScreenedNelderMead","category":"section","text":"ScreenedNelderMead(; max_evaluations=60, screen=true, kappa=1.0, target_transform=:log10,\n    fit=true, polish_radius=1/32, tolerance=1e-8, seed=0, swarm_box=nothing, particles=10)\n\nHow optimize_constants! and simplex_search minimize, within max_evaluations loss calls (the initial simplex included). Both modes start as Optim.NelderMead() does: the given constants and one vertex per constant, moved by half its value plus 0.025 (by 0.025 where that vanishes, at -0.05).\n\nscreen = false: Nelder-Mead on the loss, the steps of Optim.NelderMead() (the adaptive parameters of Gao and Han, its stopping rule).\nscreen = true: every further loss call goes where a Gaussian process over the constants (a GaussianProcess with fit choosing its length scale and noise by the marginal likelihood, on the target_transform of the loss) expects the minimum: the minimum of mean - kappa * deviation inside a trust region around the best constants scored, in units of the initial steps. The region doubles after two improvements in a row and halves after max(2, ceil(n / 2)) failures in a row; the bound turns greedy as it shrinks below the initial steps. A failed call (not finite) counts as the worst value scored. Below polish_radius initial steps, Nelder-Mead finishes on the loss from scored constants near the best ones.\ntolerance: Nelder-Mead stops when the deviation of the values at the vertices, times sqrt(n / (n + 1)), falls below it, as in Optim; seed seeds the random starts of the search on the process and the swarm.\nswarm_box: a particle swarm screened by a process explores a box first, for a loss with several minima: (lower, upper), which must contain the start, or a number r of initial steps around the start (the form for fit!, whose models differ in their constants). The start and a Latin hypercube of the box, particles points in all, are scored; then every iteration moves every particle (constriction coefficients, the best of the swarm) and the loss scores the new position the process ranks best, one call per iteration. After 2n + 4 calls without a gain of 0.1 %, or at half the budget, the trust region search continues from the best point on every point scored; it is not bound to the box. It needs screen = true.\n\nWhich variant suits which loss, with measurements: Coefficient Tuning."},{"title":"optimize_constants!","page":"API Reference","location":"api-reference.html#optimize_constants!","category":"section","text":"optimize_constants!(chromosome::Chromosome, loss::Function; method=ScreenedNelderMead(),\n    objective=nothing) -> Union{SimplexSearch,Nothing}\n\nTunes the constants of chromosome against loss(chromosome, validate), the custom loss of a search: one parameter per occurrence of a constant in expression_raw (constant_positions(chromosome)), starting from the values the chromosome holds. Every candidate is set as the chromosome's optimised_constants and scored by loss(chromosome, true), so the loss must evaluate by a path that applies them: chromosome(ctx), split_predict, predictT(regressor, chromosome). objective turns the fitness tuple into the value minimized: nothing for the mean of its entries (the order of the population), an index, or a function of the tuple. If the best constants beat the ones held, they stay in optimised_constants and the chromosome takes the fitness the loss gave them; otherwise, and if the loss throws, the chromosome is left as it was. Returns nothing for a chromosome without constants."},{"title":"simplex_search and SimplexSearch","page":"API Reference","location":"api-reference.html#simplex_search-and-SimplexSearch","category":"section","text":"simplex_search(f, x0::AbstractVector{<:Real}; method=ScreenedNelderMead()) -> SimplexSearch\n\nMinimizes f(x), a number for a vector, e.g. the error of a simulation for the coefficients x, within method.max_evaluations calls; a value that is not finite counts as the worst. The SimplexSearch holds the best point f scored (minimizer, minimum), the calls (evaluations), how many of them the process placed (proposals), the best value after every call (history), and every point scored with its value (points, values).\n\ncalibrate(p) = simulation_error(p)                 # one simulation per call\nresult = simplex_search(calibrate, [1.0, 0.5, 2.0]; method=ScreenedNelderMead(max_evaluations=50))\nresult.minimizer, result.minimum, result.evaluations"},{"title":"Evaluation Strategies","page":"API Reference","location":"api-reference.html#Evaluation-Strategies","category":"section","text":"fit! builds one of these and hands it to runGep; they are only needed to call runGep directly."},{"title":"StandardRegressionStrategy","page":"API Reference","location":"api-reference.html#StandardRegressionStrategy","category":"section","text":"Evaluates scalar models on data arrays.\n\nStandardRegressionStrategy{T}(operators, x_data, y_data, x_data_test, y_data_test,\n    loss_function::Function;\n    validation_loss_function=nothing,\n    secOptimizer=nothing,\n    break_condition=nothing,\n    penalty::T=zero(T),\n    crash_value::T=typemax(T),\n    linear_scaling::Bool=false,\n    buffered=nothing) where {T<:AbstractFloat}\n\nbuffered is the evaluation context from build_buffers(regressor, x_data) (without it every candidate scores crash_value); crash_value is the fitness of a candidate that cannot be evaluated, Inf for floating-point T. operators, x_data and penalty are stored but not used."},{"title":"GenericRegressionStrategy","page":"API Reference","location":"api-reference.html#GenericRegressionStrategy","category":"section","text":"Hands the chromosomes to a user loss, supporting several objectives.\n\nGenericRegressionStrategy(operators, number_of_objectives::Int, loss_function::Function;\n    validation_loss_function=nothing,\n    secOptimizer=nothing,\n    break_condition=nothing)"},{"title":"Core GEP Functions","page":"API Reference","location":"api-reference.html#Core-GEP-Functions","category":"section","text":""},{"title":"runGep","page":"API Reference","location":"api-reference.html#runGep","category":"section","text":"The evolutionary loop.\n\nrunGep(epochs::Int, population_size::Int, toolbox::Toolbox, evalStrategy::EvaluationStrategy;\n    hof::Int=3,\n    correction_callback=nothing,\n    homogeneity_check=nothing,\n    population_seeder=nothing,\n    correction_epochs::Int=1,\n    correction_amount::Real=0.6,\n    tourni_size::Int=3,\n    optimization_epochs::Int=500,\n    file_logger_callback=nothing,\n    save_state_callback=nothing,\n    load_state_callback=nothing,\n    population_sampling_multiplier::Int=100,\n    inputs_::Int=0,\n    cache_size::Int=10000,\n    penalty::AbstractFloat=2.0,\n    surrogate=nothing)\n\nSome defaults differ from fit!'s (correction_amount, optimization_epochs, population_sampling_multiplier); cache_size is the capacity of the fitness cache, keyed by karva string. surrogate is a SurrogateScreening; what it changes in the steps below is listed there.\n\nReturns: (best, history): the hof best chromosomes and the training history.\n\nEach epoch:\n\nWith a dimensional target, new individuals are checked and, if needed, repaired (correction_callback, homogeneity_check); the others get the worst fitness instead of being scored\nNew individuals are scored in parallel, once per distinct karva string, each thread taking the next one as soon as it is free; duplicates of known karva strings take the cached fitness times penalty\nThe population is ranked by mean fitness; every optimization_epochs epochs, if the best has improved since the last time, the strategy's secOptimizer tunes it\nThe best is re-scored with validate = true, its training and validation loss are recorded, and break_condition(population, epoch) may stop the run\nParents are selected (tournament of tourni_size, or NSGA-II with several objectives) and, unless this is the last epoch, their offspring take ranks population_size - m to population_size - 1 (see Population Dynamics)"},{"title":"Toolbox","page":"API Reference","location":"api-reference.html#Toolbox","category":"section","text":"The GEP configuration: alphabet, arities, operators, gene layout and operator probabilities.\n\nToolbox(gene_count::Int, head_len::Int, symbols::OrderedDict{Int8,Int8},\n       gene_connections::Vector{Int8}, callbacks::Dict, nodes::OrderedDict,\n       gep_probs::Dict{String,AbstractFloat};\n       unary_prob::Real=0.1, preamble_syms=Int8[],\n       number_of_objectives::Int=1, operators_=nothing,\n       function_complile=compile_djl_datatype,\n       tail_weights_=nothing, head_tail_balance::Real=0.5, ...)\n\nFields (selection):\n\ngene_count, head_len: Gene layout\nsymbols::OrderedDict{Int8,Int8}: Every symbol and its arity\ngene_connections::Vector{Int8}: The connector symbols\nheadsyms, tailsyms: Symbols allowed in heads and tails\ncallbacks: The operator of every function symbol\nnodes: The terminal behind every terminal symbol (feature selector or constant)\ngen_start_indices::Vector{Int}: Position of every gene in a chromosome\ngep_probs: Operator probabilities; for the regressors, the dictionary RegressionWrapper.GENE_COMMON_PROBS itself (see Genetic Operators)\nfitness_reset::Tuple: The worst fitness (all Inf) and the unscored fitness (all NaN)"},{"title":"Chromosome","page":"API Reference","location":"api-reference.html#Chromosome","category":"section","text":"An individual: a linear chromosome and the model it encodes.\n\nChromosome(genes::Vector{Int8}, toolbox::Toolbox, compile::Bool=false)\n\nFields:\n\ngenes::Vector{Int8}: The connectors, then the genes (head and tail each), then the preamble symbols, if any\nexpression_raw::Vector{Int8}: The karva string: the connectors, then each gene's active part in prefix order\nfitness::Tuple: Fitness, one entry per objective (NaN until scored)\ncompiled::Bool: Whether expression_raw has been resolved; editing genes does not reset it\ndimension_homogene::Bool: Set once the expression is known to meet the target dimension\noptimised_constants, scaling_weights: Fitted constants and gene coefficients, or nothing\ntoolbox::Toolbox: The configuration it was built with\n\nchromosome.compiled_function, where older code read the compiled expression, still works: it gives the model, which prints as equation_string(chromosome) and predicts like chromosome(x) when called as m(x) or m(x, operators) (x with one row per feature)."},{"title":"compile_expression!","page":"API Reference","location":"api-reference.html#compile_expression!","category":"section","text":"compile_expression!(chromosome::Chromosome; force_compile::Bool=false)\n\nResolves the genes into expression_raw, which is what the evaluator runs, if the chromosome is not compiled yet or force_compile is set; this clears optimised_constants and scaling_weights and resets the fitness to unscored. After editing genes directly, call it with force_compile=true."},{"title":"generategene / generatechromosome / generate_population","page":"API Reference","location":"api-reference.html#generate*gene-/-generate*chromosome-/-generate_population","category":"section","text":"generate_gene(headsyms, tailsyms, headlen, tail_weights, head_weights; rng=...)\ngenerate_chromosome(toolbox::Toolbox; rng=...)\ngenerate_population(number::Int, toolbox::Toolbox)\n\nRandom genes, compiled chromosomes and populations for a toolbox."},{"title":"splitkarva / splitpredict / split_equations","page":"API Reference","location":"api-reference.html#split*karva-/-split*predict-/-split_equations","category":"section","text":"split_karva(chromosome::Chromosome, coeffs::Int=2)\nsplit_positions(chromosome::Chromosome, coeffs::Int=2)\nsplit_predict(chromosome::Chromosome, ctx, coeffs::Int=2)\nsplit_equations(chromosome::Chromosome, coeffs::Int=2)\n\nsplit_karva splits the chromosome into coeffs karva strings of consecutive genes, each with its own connectors (the first coeffs - 1 connectors are dropped, and each part takes gene_count ÷ coeffs genes) – the building block of template models with several factors, and of a chromosome that carries several expressions, e.g. the right-hand sides of a system of equations. split_positions gives the positions of the symbols of each part in expression_raw. split_predict evaluates the parts in a buffer context (buffer_context, one per thread from thread_contexts) and returns their outputs, copied out of the context's buffers; an entry that is not a vector marks a part that cannot be evaluated. split_equations writes each part as an equation string. Both apply the tuned constants of the chromosome (optimised_constants), the equations rounded to 6 significant digits."},{"title":"EvoSelection.SelectedMembers","page":"API Reference","location":"api-reference.html#EvoSelection.SelectedMembers","category":"section","text":"The result of a selection: indices::Vector{Int} of the selected individuals, and fronts (the Pareto fronts by rank, after NSGA-II; empty after tournament selection)."},{"title":"Loss Functions","page":"API Reference","location":"api-reference.html#Loss-Functions","category":"section","text":""},{"title":"Built-in Loss Functions","page":"API Reference","location":"api-reference.html#Built-in-Loss-Functions","category":"section","text":"get_loss_function(name) returns the function behind a name (an unknown name throws a KeyError); fit! accepts the names directly (loss_fun=\"mse\"). Every one takes (y_true, y_pred), two arrays of equal length and element type.\n\n\"mse\": Mean squared error\n\"rmse\": Root mean squared error\n\"mae\": Mean absolute error\n\"nrmse\": Root mean squared error divided by the standard deviation of y_true\n\"srsme\": Relative root mean squared error (residuals divided by the target's magnitude)\n\"r2_score\": Coefficient of determination – a score, higher is better\n\"r2_score_f\": r2_score on data rescaled by a power of ten, for very large or small magnitudes\n\"xi_core\": A rank correlation modelled on Chatterjee's ξ – a score\n\nThe search minimises its loss; use the scores for reporting."},{"title":"Custom Loss Functions","page":"API Reference","location":"api-reference.html#Custom-Loss-Functions","category":"section","text":""},{"title":"Single-Objective Custom Loss","page":"API Reference","location":"api-reference.html#Single-Objective-Custom-Loss","category":"section","text":"using Statistics\n\n# regressor, x_data (one row per sample), y_data, epochs and population_size as in the examples\n# mean absolute error, weighting the residuals of large targets less\nfunction custom_loss(y_true, y_pred)\n    return mean(abs.(y_true .- y_pred) ./ (1 .+ abs.(y_true)))\nend\n\nfit!(regressor, epochs, population_size, x_data', y_data; loss_fun=custom_loss)"},{"title":"Multi-Objective Custom Loss","page":"API Reference","location":"api-reference.html#Multi-Objective-Custom-Loss","category":"section","text":"using Statistics\n\n# n_features, x_data (one row per sample), y_data, epochs and population_size as in the examples\nregressor = GepRegressor(n_features; number_of_objectives=2)\nctxs = thread_contexts(regressor.toolbox_, x_data')\n\nfunction multi_objective_loss(elem, validate::Bool)\n    if isnan(mean(elem.fitness)) || validate\n        y_pred = try\n            elem(ctxs[Threads.threadid()])\n        catch\n            nothing\n        end\n        if y_pred isa AbstractVector && all(isfinite, y_pred)\n            mse = mean(abs2, y_data .- y_pred)                     # objective 1: accuracy\n            complexity = 0.01 * length(elem.expression_raw)      # objective 2: size, scaled\n            elem.fitness = (mse, complexity)\n        else\n            elem.fitness = (Inf, Inf)\n        end\n    end\nend\n\nfit!(regressor, epochs, population_size, multi_objective_loss)\n\nInf is a valid penalty: tournament selection leaves out individuals whose (first) objective is not finite, falling back to the whole population when none is finite, and NSGA-II ranks tuples with more non-finite entries behind."},{"title":"Tensor Custom Loss","page":"API Reference","location":"api-reference.html#Tensor-Custom-Loss","category":"section","text":"using LinearAlgebra, Statistics\n\n# regressor: a GepTensorRegressor after allocate_buffers!; target_tensors: the target column\nfunction tensor_loss(elem, validate::Bool)\n    if isnan(mean(elem.fitness)) || validate\n        predictions = try\n            predictT(regressor, elem.expression_raw)\n        catch\n            nothing\n        end\n        if predictions isa AbstractVector && length(predictions) == length(target_tensors) &&\n           eltype(predictions) == eltype(target_tensors)\n            total_error = sum(norm(predictions[i] - target_tensors[i])^2\n                              for i in eachindex(target_tensors))\n            elem.fitness = (total_error / length(target_tensors),)\n        else\n            elem.fitness = (1e6,)    # e.g. a scalar where a vector belongs\n        end\n    end\nend"},{"title":"Template loss","page":"API Reference","location":"api-reference.html#Template-loss","category":"section","text":"Template losses enable multi-expression formulations or fixed templates like f(x_1x_n)=v(x_1x_2) + g(x_3): split_karva splits a chromosome into groups of genes, and calc_stack_batch_tensor evaluates each group on the input columns (for a GepRegressor, split_predict(elem, ctx, 2) evaluates the groups in a buffer context, as examples/Main_surrogate_multi_objective.jl does). Here with a GepTensorRegressor, whose toolbox holds the evaluator's operator objects:\n\nusing LinearAlgebra, Statistics\n\n# inputs: Dict{Int8,Any}, one column per terminal symbol -- regressor.input_values after\n# allocate_buffers!; t1, t2: your two basis columns; a_true: the target column\nfunction template_loss(elem, validate::Bool)\n    if isnan(mean(elem.fitness)) || validate\n        try\n            g1, g2 = split_karva(elem, 2)\n            p1 = calc_stack_batch_tensor(g1, regressor.toolbox_.callbacks, inputs, nothing)\n            p2 = calc_stack_batch_tensor(g2, regressor.toolbox_.callbacks, inputs, nothing)\n            a_pred = @. p1 * t1 + p2 * t2\n            elem.fitness = (norm(a_true - a_pred),)\n        catch\n            elem.fitness = (1e6,)\n        end\n    end\nend"},{"title":"Selection Methods","page":"API Reference","location":"api-reference.html#Selection-Methods","category":"section","text":""},{"title":"Tournament Selection","page":"API Reference","location":"api-reference.html#Tournament-Selection","category":"section","text":"The selection for a single objective: each parent is the best of tourni_size individuals drawn with replacement from those with a finite fitness, identical fitness values counting once; if no fitness is finite, from the whole population. The best individual is always among the parents. fit! uses tournaments of 3 % of the population (0.3 % for tensor regression), at least 3."},{"title":"NSGA-II Selection","page":"API Reference","location":"api-reference.html#NSGA-II-Selection","category":"section","text":"The selection for several objectives (GepRegressor(n; number_of_objectives=2) with a custom loss): Pareto ranks by non-dominated sorting, and tournaments of 3 decided by rank, then by crowding distance.\n\ndominates_(a, b) tells whether fitness tuple a dominates b (a tuple with fewer non-finite entries dominates one with more), which is how to pick the non-dominated models out of best_models_."},{"title":"Genetic Operators","page":"API Reference","location":"api-reference.html#Genetic-Operators","category":"section","text":"The probabilities and rates of the genetic operators are the entries of RegressionWrapper.GENE_COMMON_PROBS. Every toolbox holds this dictionary itself, not a copy, so a change applies to existing regressors too:\n\nusing GeneExpressionProgramming\nprobs = GeneExpressionProgramming.RegressionWrapper.GENE_COMMON_PROBS\n\nprobs[\"mutation_rate\"] = 0.1\n\nlist_all_genetic_params() returns a copy of the current values. Crossover and fusion probabilities are per pair of parents, the others per offspring. Core Concepts describes each operator.\n\nKey Default Meaning\none_point_cross_over_prob 0.5 one-point crossover\ntwo_point_cross_over_prob 0.4 two-point crossover\nmutation_prob 1.0 point mutation\nmutation_rate 0.15 a mutation redraws round(0.15 × length) positions, drawn with replacement\ninversion_prob 0.1 inversion of head symbols\ninsertion_prob 0.1 a random terminal written into a head position\nroot_insertion_prob 0.1 rotation of a gene's head, changing its root\nreverse_insertion_tail 0.0 rotation within a gene's tail\ngene_transposition_prob 0.1 exchange of two tail segments\ngene_averaging_prob 1.0 gene averaging towards the consensus of the elite\ngene_averaging_rate 0.3 probability per position of taking the consensus symbol\ngene_averaging_elite_frac 0.3 elite size, as a fraction of the mating size (at least 3)\ndominant_fusion_prob, rezessiv_fusion_prob, fusion_prob 0.0 each fusion operators\ndominant_fusion_rate, rezessiv_fusion_rate, fusion_rate 0.1, 0.1, 0.0 share of positions a fusion draws\nmating_size 0.7 offspring per epoch, as a fraction of the population size"},{"title":"Function Sets","page":"API Reference","location":"api-reference.html#Function-Sets","category":"section","text":""},{"title":"Scalar Functions","page":"API Reference","location":"api-reference.html#Scalar-Functions","category":"section","text":"Every function in FUNCTION_LIB_COMMON can be entered by its symbol:\n\nbasic_functions = [:+, :-, :*, :/]\npower_functions = [:sqr, :sqrt, :^]\nexp_log_functions = [:exp, :log, :log10, :log2]\ntrig_functions = [:sin, :cos, :tan, :asin, :acos, :atan, :sinh, :cosh, :tanh, :asinh, :acosh, :atanh]\nother_functions = [:abs, :sign, :floor, :ceil, :round, :min, :max]\n\nUnder physical dimensions, min and max take operands of one dimension, abs keeps its operand's, sign takes any and gives a dimensionless result, and floor, ceil and round, like exp or sin, take dimensionless operands only: rounding a quantity with units would give a result that depends on the units it is expressed in.\n\nlist_all_functions() lists each with its arity and its unit rules; list_all_arity(), list_all_forward_handlers() and list_all_backward_handlers() return copies of the single tables. set_function!(sym, func), set_arity!(sym, arity::Int8), set_forward_handler!(sym, handler), set_backward_handler!(sym, handler) and update_function!(sym; func, arity, forward_handler, backward_handler) change an existing entry, for regressors built afterwards; a symbol that is not in the library throws an ArgumentError. The batched evaluator runs only functions it has an operator node for (the functions behind TENSOR_NODES). A regressor with any other function cannot be used: the data method of fit! throws an ArgumentError, so does predicting with it, buffer_context and thread_contexts return nothing, and the custom-loss method of fit! fails while it samples the initial population.\n\n# abs of dimensionless operands only\nupdate_function!(:abs; forward_handler=zero_unit_forward, backward_handler=zero_unit_backward)"},{"title":"Tensor Operations","page":"API Reference","location":"api-reference.html#Tensor-Operations","category":"section","text":"On top of the scalar functions, GepTensorRegressor accepts:\n\nProducts: :* (products with a scalar), :dot (single contraction), :dcontract (double contraction), :otimes (outer product), :crossp (cross product of 3D vectors), :hadamard (element-wise)\nInvariants and norms: :tr, :det, :norm\nParts and derived tensors: :symmetric, :skew, :dev, :vol, :inv, :tdot and :dott (both A·Aᵀ), :lap\n\nWith considered_dimensions, only the functions with tensor unit rules can be entered: :+, :-, :*, :/, :inv, :dot, :crossp, :tr, :det, :dcontract, :lap, :hadamard, :sqrt, :norm, :log, :exp, :sin and :cos.\n\nThe tensors are Tensors.jl types:\n\nusing Tensors\n\nvector_3d = rand(Tensor{1,3})\nmatrix_3x3 = rand(Tensor{2,3})"},{"title":"Physical Dimensionality","page":"API Reference","location":"api-reference.html#Physical-Dimensionality","category":"section","text":""},{"title":"Dimension Representation","page":"API Reference","location":"api-reference.html#Dimension-Representation","category":"section","text":"Physical dimensions are 7-element Float16 vectors of SI exponents, in the order [kg, m, s, K, mol, A, cd]:\n\n# [Mass, Length, Time, Temperature, Amount of substance, Current, Luminous intensity]\nvelocity_dim = Float16[0, 1, -1, 0, 0, 0, 0]    # [L T⁻¹]\nforce_dim = Float16[1, 1, -2, 0, 0, 0, 0]       # [M L T⁻²]\nenergy_dim = Float16[1, 2, -2, 0, 0, 0, 0]      # [M L² T⁻²]\ncurrent_density_dim = Float16[0, -2, 0, 0, 0, 1, 0]   # [I L⁻²]\n\nOn the tensor path the vector carries the tensor order in front of these."},{"title":"Dimensional Constraints","page":"API Reference","location":"api-reference.html#Dimensional-Constraints","category":"section","text":"# x_data: a mass, a length and a time per row (sample); y_data: a velocity per sample;\n# epochs and population_size as in the examples\nfeature_dims = Dict{Symbol,Vector{Float16}}(\n    :x1 => Float16[1, 0, 0, 0, 0, 0, 0],    # Mass\n    :x2 => Float16[0, 1, 0, 0, 0, 0, 0],    # Length\n    :x3 => Float16[0, 0, 1, 0, 0, 0, 0],    # Time\n)\n\ntarget_dim = Float16[0, 1, -1, 0, 0, 0, 0]  # Velocity\n\nregressor = GepRegressor(3;\n                        considered_dimensions=feature_dims,\n                        max_permutations_lib=10000)\n\nfit!(regressor, epochs, population_size, x_data', y_data;\n     target_dimension=target_dim)\n\nA constant terminal takes a dimension under its symbol, e.g. Symbol(9.807) => get_constant_dims(\"g\") with entered_terminal_nums=[Symbol(9.807)]."},{"title":"Checking and Repairing Expressions","page":"API Reference","location":"api-reference.html#Checking-and-Repairing-Expressions","category":"section","text":"is_dimensionally_homogeneous(expression::Vector{Int8}, target_dimension, token_dto)\ndimensional_homogeneity_distance(expression::Vector{Int8}, target_dimension, token_dto)\nis_gene_wise_homogeneous(expression::Vector{Int8}, target_dimension, token_dto, gene_count)\ngene_dimensions(expression::Vector{Int8}, gene_count, token_dto)\ncorrect_genes!(genes, start_indices, expression, target_dimension, token_dto;\n               cycles=5, gene_len=0, head_len=0, connectors=nothing, work_limit=800,\n               gene_wise=false)\nsample_lib_expression(target_dimension, token_dto; max_len, exact_only=false, head_len=0)\n\nis_dimensionally_homogeneous / dimensional_homogeneity_distance: Forward check of a karva string against a target (the distance is Inf16 for an expression with an inconsistency anywhere)\nis_gene_wise_homogeneous / gene_dimensions: The same gene by gene, the check a model scored as the weighted sum of its genes (linear scaling) needs\ncorrect_genes!: The repair fit! uses. It pushes the target down the expression and applies the cheapest fixes – swapping terminals or operators, splitting a requirement between operands, replacing subexpressions with library expressions – within the gene layout (gene_len, head_len, connectors). Returns (distance, success) and leaves genes untouched on failure; recompile the chromosome after a success. With gene_wise=true every gene is repaired to the target on its own, and the connectors become + or - if connectors offer one\nsample_lib_expression: A random library-backed expression of (or near) a dimension, in prefix order\n\nExample (regressor and target_dim as above):\n\ntb, dto = regressor.toolbox_, regressor.token_dto_\nc = generate_chromosome(tb)\n_, ok = correct_genes!(c.genes, tb.gen_start_indices, c.expression_raw, target_dim, dto;\n                       gene_len=2 * tb.head_len + 1, head_len=tb.head_len,\n                       connectors=tb.gene_connections, cycles=10)\nok && compile_expression!(c; force_compile=true)\nis_dimensionally_homogeneous(c.expression_raw, target_dim, dto)"},{"title":"Physical Constants","page":"API Reference","location":"api-reference.html#Physical-Constants","category":"section","text":"get_constant(name)          # (value, dimension)\nget_constant_value(name)\nget_constant_dims(name)\nphysical_constants          # Dict of common constants, e.g. \"c\", \"G\", \"h\", \"k_B\", \"e\"\nphysical_constants_all      # a larger set; the get_constant* functions look up physical_constants only"},{"title":"Units from a Description File","page":"API Reference","location":"api-reference.html#Units-from-a-Description-File","category":"section","text":"get_feature_dims_json(case_data, feature_names, case_name) and get_target_dim_json(case_data, case_name) read the dimensions of an equation from a parsed JSON description such as assets/case_dsc.json, as paper/ConstraintViaSBP.jl does. The feature dimensions come keyed by the names in feature_names as Strings; convert the keys to Symbols for considered_dimensions."},{"title":"Utility Functions","page":"API Reference","location":"api-reference.html#Utility-Functions","category":"section","text":""},{"title":"traintestsplit","page":"API Reference","location":"api-reference.html#train*test*split","category":"section","text":"train_test_split(X::AbstractMatrix{T}, y::AbstractVector{T}; train_ratio::T=0.9, consider::Int=1)\n\nShuffles the rows of X (one sample per row) and y with the global RNG, splits them at train_ratio, and keeps every consider-th row of each part.\n\nReturns: (x_train, y_train, x_test, y_test)\n\nExample:\n\nx_train, y_train, x_test, y_test = train_test_split(X, y; train_ratio=0.8)"},{"title":"Other Utilities","page":"API Reference","location":"api-reference.html#Other-Utilities","category":"section","text":"minmax_scale(X; feature_range=(0, 1)): A copy of X with each column mapped linearly onto feature_range\nisclose(a, b; rtol=1e-5, atol=1e-8): abs(a - b) <= atol + rtol * abs(b)\nsave_state(filename, state) / load_state(filename): Serialize and restore, for example a population in save_state_callback / load_state_callback\nthread_slots(): The number of per-thread slots buffers are sized by (Threads.maxthreadid())\nallfinite(A): all(isfinite, A) for a float array, in one vectorised pass without early exit\ncalc_stack_batch_tensor(rek_string, callbacks, inputs, buffers): The evaluator itself: runs a karva string on input columns"},{"title":"Error Handling","page":"API Reference","location":"api-reference.html#Error-Handling","category":"section","text":""},{"title":"Common Errors","page":"API Reference","location":"api-reference.html#Common-Errors","category":"section","text":""},{"title":"ArgumentError: an operator or terminal in this regressor has no batched counterpart","page":"API Reference","location":"api-reference.html#ArgumentError:-an-operator-or-terminal-in-this-regressor-has-no-batched-counterpart","category":"section","text":"A function in the regressor has no node in the batched evaluator (see Function Sets)."},{"title":"ArgumentError: a target_dimension needs the features' dimensions","page":"API Reference","location":"api-reference.html#ArgumentError:-a-target_dimension-needs-the-features'-dimensions","category":"section","text":"fit! got a target_dimension for a regressor built without considered_dimensions."},{"title":"ArgumentError: linear_scaling writes the scaled model as a sum of weighted genes","page":"API Reference","location":"api-reference.html#ArgumentError:-linear_scaling-writes-the-scaled-model-as-a-sum-of-weighted-genes","category":"section","text":"linear_scaling=true needs :+ and :* among the functions."},{"title":"KeyError from getlossfunction","page":"API Reference","location":"api-reference.html#KeyError-from-get*loss*function","category":"section","text":"The loss name is not one of the built-in losses."},{"title":"An error inside a custom loss","page":"API Reference","location":"api-reference.html#An-error-inside-a-custom-loss","category":"section","text":"An exception thrown inside a custom loss is not caught by the search: it stops fit!. Catch evaluation errors inside the loss and assign a penalty."},{"title":"Configuration Example","page":"API Reference","location":"api-reference.html#Configuration-Example","category":"section","text":"A larger search with more functions and held-out data (x_train, x_test: 5 features, one row per sample; y_train, y_test: the targets):\n\nregressor = GepRegressor(\n    5;                                    # 5 input features\n    gene_count = 3,                       # 3 genes per chromosome\n    head_len = 8,                         # Longer expressions\n    entered_non_terminals = [:+, :-, :*, :/, :sin, :cos, :exp]\n)\n\nfit!(regressor, 1500, 2000, x_train', y_train;   # 1500 epochs, population of 2000\n     x_test = x_test',\n     y_test = y_test,\n     loss_fun = \"rmse\")\n\nFor additional examples and use cases, refer to the examples, starting with Basic Regression."},{"title":"Tensor Regression","page":"Tensor Regression","location":"examples/tensor-regression.html#Tensor-Regression","category":"section","text":"Tensor regression evolves expressions over vector and tensor data, for applications such as computational mechanics and fluid dynamics, where the relationships involve vectors and higher-order tensors. GeneExpressionProgramming.jl supports it either with fixed templates of several expressions, in the manner of M-GEP [1] – see the template loss – or with a free search over tensor operations, shown here."},{"title":"Tensor Operations in GeneExpressionProgramming.jl","page":"Tensor Regression","location":"examples/tensor-regression.html#Tensor-Operations-in-GeneExpressionProgramming.jl","category":"section","text":"GepTensorRegressor evaluates candidates with the same batched evaluator as the scalar path, over Tensors.jl types, with buffers allocated once per thread and tensor type. Its operations include vector addition and subtraction, products with a scalar, dot and cross products, double contraction, element-wise products, traces, determinants, norms and the parts of a tensor; Tensor Operations lists them."},{"title":"Tensor Regression Example","page":"Tensor Regression","location":"examples/tensor-regression.html#Tensor-Regression-Example","category":"section","text":"The example recovers a vector-valued relationship between velocity-like vectors and scalars.\n\nusing GeneExpressionProgramming\nusing Random\nusing Tensors\nusing LinearAlgebra\nusing Statistics\n\nRandom.seed!(789)\n\nprintln(\"Target: a = 0.5*u1 + x2*u2 + 2*u3\")\nprintln(\"where u1, u2, u3 are 3D vectors and x2 is a scalar\")\n\n# ---------------------------------------------------------------- data --------\nn_samples = 300\n\nx1 = [2.0 for _ in 1:n_samples]   # a constant scalar column\nx2 = randn(n_samples)             # a varying scalar column\nu1 = [Tensor{1,3}(randn(3)) for _ in 1:n_samples]\nu2 = [Tensor{1,3}(randn(3)) for _ in 1:n_samples]\nu3 = [Tensor{1,3}(randn(3)) for _ in 1:n_samples]\n\na_true = [0.5 * u1[i] + x2[i] * u2[i] + 2.0 * u3[i] for i in 1:n_samples]\n\n# One column per feature. Unlike the scalar path, which takes a matrix, the tensor path\n# takes a column per feature because the columns have different element types -- scalars\n# here, 3D vectors there. A tuple or a `Vector{Any}` both work.\ninputs = (x1, x2, u1, u2, u3)\n\n# ------------------------------------------------------------ regressor -------\nregressor = GepTensorRegressor(5;\n    problem_dimension=3,                       # 3D tensors\n    gene_count=3,                              # one gene per additive term\n    head_len=4,\n    entered_non_terminals=[:+, :-, :*],\n    entered_terminal_nums=[0.5, 2.0],          # constants the search may use\n    gene_connections=[:+, :-],\n    feature_names=[\"x1\", \"x2\", \"U1\", \"U2\", \"U3\"])\n\n# Evaluation buffers are allocated once, against the data the search will score on, and\n# reused for every candidate. This must be called before `fit!`.\nallocate_buffers!(regressor, inputs)\n\n# --------------------------------------------------------------- loss ---------\n# The tensor path takes a loss *callback* rather than a loss name: it is handed each\n# chromosome and sets its fitness. `predictT` evaluates the chromosome's karva string\n# through the preallocated buffers.\n#\n# A candidate that cannot be scored gets a large finite penalty, which keeps it eligible\n# for the tournaments; `Inf` would work too -- tournament selection leaves non-finite\n# fitness values out, and falls back to the whole population when none is finite.\nconst PENALTY = 1e6\n\n@inline function tensor_loss(elem, validate::Bool)\n    if isnan(mean(elem.fitness)) || validate\n        try\n            pred = predictT(regressor, elem.expression_raw)\n            # a type-invalid chromosome -- a scalar where a vector belongs, say -- comes\n            # back as something other than a vector of 3D tensors\n            if pred isa AbstractVector && length(pred) == n_samples &&\n               eltype(pred) <: Tensor{1,3}\n                l = mean(norm(pred[i] - a_true[i])^2 for i in 1:n_samples)\n                elem.fitness = (isfinite(l) ? l : PENALTY,)\n            else\n                elem.fitness = (PENALTY,)\n            end\n        catch\n            elem.fitness = (PENALTY,)\n        end\n    end\nend\n\n# ------------------------------------------------------------ evolution -------\nepochs = 60\npopulation_size = 600\n\ntraining_time = @elapsed fit!(regressor, epochs, population_size, tensor_loss)\nprintln(\"Training completed in $(round(training_time, digits=2)) seconds\")\n\n# -------------------------------------------------------------- results ------\nbest = regressor.best_models_[1]\nprintln(\"Best expression : \", print_karva_strings(best))\nprintln(\"Best fitness    : \", best.fitness[1])\n\npred = predictT(regressor, best.expression_raw)\nvector_errors = [norm(pred[i] - a_true[i]) for i in 1:n_samples]\nprintln(\"Mean vector error: \", mean(vector_errors))\nprintln(\"Max vector error : \", maximum(vector_errors))\n\ntotal_variance = sum(norm(a_true[i] - mean(a_true))^2 for i in 1:n_samples)\nresidual_variance = sum(norm(pred[i] - a_true[i])^2 for i in 1:n_samples)\nprintln(\"R² equivalent    : \", 1 - residual_variance / total_variance)\n\nWith this seed the search recovers the target exactly, as\n\n(((U3 + (U2 * x2)) + U3) + (U1 * 0.5))\n\nwhich is 2*U3 + x2*U2 + 0.5*U1 — the relationship the data was generated from, at a mean squared error of about 1e-31.\n\nTo predict on new data, pass one column per feature, in the same order and of any length: predictT(regressor, best.expression_raw, Any[x1_new, x2_new, u1_new, u2_new, u3_new]). In a loss, predictT_scaled(regressor, elem, a_true) returns the prediction with one least-squares coefficient per gene – the tensor counterpart of linear_scaling – and stores the coefficients in elem.scaling_weights; it returns nothing when no gene matches the target in length and element type, or the fit is not finite."},{"title":"Working with Other Tensor Orders","page":"Tensor Regression","location":"examples/tensor-regression.html#Working-with-Other-Tensor-Orders","category":"section","text":"The same setup handles second-order tensors; only the columns, the operations and the expected element type in the loss change:\n\n# Second-order tensor columns: stresses, strains, velocity gradients\nsigma = [rand(Tensor{2,3}) for _ in 1:n_samples]\nepsilon = [rand(Tensor{2,3}) for _ in 1:n_samples]\n\nregressor2 = GepTensorRegressor(2;\n    problem_dimension=3,\n    entered_non_terminals=[:+, :-, :*, :dot, :tr, :dev],\n    feature_names=[\"sigma\", \"epsilon\"])\nallocate_buffers!(regressor2, (sigma, epsilon))\n\n# in the loss, test for eltype(pred) <: Tensor{2,3} (or <: Number for a scalar target)"},{"title":"Physical Dimensions on the Tensor Path","page":"Tensor Regression","location":"examples/tensor-regression.html#Physical-Dimensions-on-the-Tensor-Path","category":"section","text":"With considered_dimensions, each feature dimension carries the tensor order in front of the SI exponents, keyed :x1, :x2, ... in feature order; constants are dimensionless. Only the functions with tensor unit rules can then be entered: :+, :-, :*, :/, :inv, :dot, :crossp, :tr, :det, :dcontract, :lap, :hadamard, :sqrt, :norm, :log, :exp, :sin and :cos."},{"title":"References","page":"Tensor Regression","location":"examples/tensor-regression.html#References","category":"section","text":"[1] Weatheritt, J., Sandberg, R. D. (2016)  A novel evolutionary algorithm applied to algebraic modifications of the RANS stress–strain relationship. Journal of Computational Physics, 325, 22-37\n\n\n\nNext: Surrogate Screening"},{"title":"Installation Guide","page":"Installation","location":"installation.html#Installation-Guide","category":"section","text":""},{"title":"Julia Requirements","page":"Installation","location":"installation.html#Julia-Requirements","category":"section","text":"Project.toml accepts any Julia 1.x release, but the code uses features of Julia 1.7 and later; the repository's Manifest.toml was generated with Julia 1.12.1, and the tests pass on Julia 1.12. Julia is available from the official website."},{"title":"Installation Methods","page":"Installation","location":"installation.html#Installation-Methods","category":"section","text":"The latest registered release:\n\nusing Pkg\nPkg.add(\"GeneExpressionProgramming\")\n\nThese pages follow the current code in the repository, which may be ahead of that release. To install it:\n\nusing Pkg\nPkg.add(url=\"https://github.com/maxreiss123/GeneExpressionProgramming.jl.git\")\n\nTo modify the source, install it in development mode, which clones the repository into your Julia development directory:\n\nusing Pkg\nPkg.develop(url=\"https://github.com/maxreiss123/GeneExpressionProgramming.jl.git\")\n\nor add a local copy:\n\nusing Pkg\nPkg.add(path=\"/path/to/GeneExpressionProgramming.jl\")\n\nFrom a clone, the scripts in examples/ include the sources directly and run with julia --project=. --threads=4 examples/<script>.jl. The tutorial folder holds a notebook that runs on Google Colab: a first search, then the constants of a model tuned against a loss of your own."},{"title":"Dependencies","page":"Installation","location":"installation.html#Dependencies","category":"section","text":"Pkg installs the dependencies with the package. Expressions are evaluated by the package's own batched evaluator, so there is no separate expression engine. The dependencies doing the heavy lifting are:\n\nTensors.jl: vector and tensor types and operations for GepTensorRegressor\nOptim.jl: Nelder-Mead optimisation of the numeric constants of the best model\nNearestNeighbors.jl: the kd-tree behind the unit repair's dimension lookups\nThreadsX.jl: parallel unit repair\nRandom123.jl: independent, reproducible random streams per parallel task\nLRUCache.jl: the fitness cache that detects duplicate expressions\nStatsBase.jl: weighted sampling of symbols when genes are generated\nDistributions.jl: the random constants of GepTensorRegressor\nCSV.jl / DataFrames.jl / JSON.jl: reading data files and unit descriptions in the examples and paper scripts\n\nTensors.jl, CSV.jl and DataFrames.jl are dependencies of the package; add them to your own environment to call them directly (for example using Tensors to build tensor data).\n\nPlots.jl is not a dependency. Install it to draw results:\n\nusing Pkg\nPkg.add(\"Plots\")\n\nThe scripts in examples/ print their results; Main_min_example.jl and Main_min_with_csv.jl also plot them when Plots.jl is installed."},{"title":"Threads","page":"Installation","location":"installation.html#Threads","category":"section","text":"The fitness evaluation, the genetic operators and the unit repair run in parallel on the threads Julia is started with:\n\njulia --threads=auto your_script.jl\n# or\nJULIA_NUM_THREADS=8 julia your_script.jl\n\nEvaluation buffers are allocated once per thread id (thread_slots(), which covers the interactive thread that Julia 1.12 starts next to the worker threads), so a custom loss can evaluate in ctxs[Threads.threadid()] of thread_contexts(...) without sizing anything itself.\n\nThe fitness loop runs one worker per thread, and each takes the next unscored individual as soon as it is free: a loss whose cost varies between individuals (a solver that converges quickly for some models and slowly for others) keeps every thread busy until the last one is scored. A call of the loss stays on one thread from start to finish and no other call shares its thread id meanwhile, so ctxs[Threads.threadid()] is safe even when the loss waits, e.g. on an external process."},{"title":"Verification","page":"Installation","location":"installation.html#Verification","category":"section","text":"using GeneExpressionProgramming\n\nregressor = GepRegressor(2)\nprintln(\"Basic regressor created: \", typeof(regressor))"},{"title":"Next Steps","page":"Installation","location":"installation.html#Next-Steps","category":"section","text":"Getting Started: a first symbolic regression\nCore Concepts: how the search works\nExamples: complete workflows\n\nFor help, open an issue on the GitHub repository."},{"title":"Expensive Losses: Surrogate Screening","page":"Surrogate Screening","location":"examples/surrogate-screening.html#Expensive-Losses:-Surrogate-Screening","category":"section","text":"When a single loss call is expensive – a solver in the loop, a simulation, an external program – an epoch spends most of its calls on individuals that are visibly not worth one. A SurrogateScreening, passed to fit! as surrogate, spends the loss on a few promising individuals per epoch and lets Gaussian processes predict the loss of the others. It is the Julia counterpart of gep.SurrogateBatchStrategy of the Python package, with the defaults measured there.\n\nThis page screens a search whose loss integrates an ODE, then a search with two expressions and two objectives, the right-hand sides of a system of two ODEs. It closes with what the screening guarantees, the settings worth knowing, the diagnostics, and when the screening pays off. Both searches are runnable scripts: examples/Main_surrogate_screening.jl and examples/Main_surrogate_multi_objective.jl. The constants of a model, screened the same way, have a page of their own: Coefficient Tuning."},{"title":"How the Screening Works","page":"Surrogate Screening","location":"examples/surrogate-screening.html#How-the-Screening-Works","category":"section","text":"Each epoch, the new individuals (one per karva string) go through four steps:\n\nEmbedding. The expression is evaluated on a small, fixed probe set, and its outputs (asinh-transformed) are the latent vector of the individual. Individuals that behave alike lie close together, however differently they are written. An expression that cannot be evaluated on every probe is scored as a crash, without a loss call.\nPrediction. One Gaussian process per objective maps the latent vectors of the individuals scored so far to their losses, on a log10 scale.\nSelection. An acquisition, by default the optimistic bound mean - kappa * deviation, picks the individuals the loss scores: individuals_per_epoch of them, a tenth of them at random instead, to explore.\nImputation. Every other individual receives the prediction of the processes, one float step behind the best loss scored so far on each objective, and competes with it in the selection.\n\nUntil enough individuals have been scored to fit a process (the warmup: six times the batch, at least 60), an epoch scores at most twice the batch (at least 20), picked at random, and the others receive the median loss of that batch. From 10 individuals per epoch on (read on a hundred individual epoch), each epoch also breeds three times the children the population takes, and the processes pick the ones that enter."},{"title":"A Single Objective: an ODE in the Loss","page":"Surrogate Screening","location":"examples/surrogate-screening.html#A-Single-Objective:-an-ODE-in-the-Loss","category":"section","text":"The search looks for f in dx/dt = f(x), given trajectories of the logistic equation f(x) = x - 0.5 x^2 from eight initial values. The loss integrates dx/dt = f(x) with the candidate f (RK4, all trajectories at once) and compares the result with the data, so every loss call costs a simulation.\n\nusing GeneExpressionProgramming\nusing Random\nusing Statistics\n\nRandom.seed!(1)\n\n# the data: logistic growth from eight initial values, sampled every 0.1 up to t = 8\nf_true(x) = x .- 0.5 .* x .^ 2\nx0 = collect(range(0.05, 3.5; length=8))\ndt, steps, every = 0.004, 2000, 25\n\nfunction rk4(f, x0, dt, steps, every)\n    x = copy(x0)\n    out = zeros(length(x0), steps ÷ every)\n    for s in 1:steps\n        k1 = f(x)\n        k2 = f(x .+ 0.5dt .* k1)\n        k3 = f(x .+ 0.5dt .* k2)\n        k4 = f(x .+ dt .* k3)\n        x .+= dt / 6 .* (k1 .+ 2 .* k2 .+ 2 .* k3 .+ k4)\n        all(isfinite, x) || return nothing\n        s % every == 0 && (out[:, s÷every] .= x)\n    end\n    return out\nend\n\ndata = rk4(f_true, x0, dt, steps, every)\n\nregressor = GepRegressor(1; entered_features=[:x], entered_non_terminals=[:+, :-, :*],\n    gene_count=2, head_len=4)\n\n# one buffer context per thread, whose input column (the state x) the solver overwrites at\n# every stage: the compiled program reads the column in place\nctxs = thread_contexts(regressor.toolbox_, zeros(1, length(x0)))\nx_sym = only(k for (k, n) in regressor.toolbox_.nodes if n isa InputSelector)\ncalls = Threads.Atomic{Int}(0)\n\n# the loss runs on several threads at once: `local` keeps its variables its own\nfunction loss(elem, validate::Bool)\n    isnan(mean(elem.fitness)) || validate || return\n    Threads.atomic_add!(calls, 1)\n    local ctx = ctxs[Threads.threadid()]\n    function rhs(x)\n        ctx.nodes[x_sym] .= x\n        local y = elem(ctx)\n        return y isa AbstractVector ? copy(y) : fill(NaN, length(x))\n    end\n    local sim = rk4(rhs, x0, dt, steps, every)\n    elem.fitness = isnothing(sim) ? (Inf,) : (mean(abs2, sim .- data),)\nend\n\n# the probe states span the range the trajectories visit; the latent vector of an\n# individual is its f on them\nprobes = reshape(collect(range(0.0, 3.5; length=24)), 1, :)\nsurrogate = SurrogateScreening(regressor, probes;\n    individuals_per_epoch=0.15,    # 15 % of the new individuals of an epoch\n    seed=1)\n\nfit!(regressor, 40, 200, loss; surrogate=surrogate)\n\nbest = regressor.best_models_[1]\nprintln(best, \"   loss \", best.fitness[1])\nprintln(\"solver calls \", calls[], \", predictions \", surrogate.imputed_count)\n\nThe loss is the one a search without screening would use; the screening only decides which individuals reach it. Three choices matter:\n\nThe probes: one row per feature and one column per probe sample, like the training data of fit!. A few dozen samples from the range that matters suffice; for an ODE, the states its trajectories visit.\nThe batch: individuals_per_epoch is a count (10 by default), which pins the loss calls per epoch, or a share in (0, 1), which adapts them to the new individuals of an epoch.\nThe seed: seed fixes the random choices of the screening, so that a seeded search reproduces.\n\nexamples/Main_surrogate_screening.jl runs this search with and without the screening, from the same seed. Both find x - 0.5 x^2 exactly; the screened search after 776 solver calls, the other after 5,423."},{"title":"Several Expressions and Objectives: a System of ODEs","page":"Surrogate Screening","location":"examples/surrogate-screening.html#Several-Expressions-and-Objectives:-a-System-of-ODEs","category":"section","text":"The setting of the Python tutorial ext_eval_multi_objective_screened_gep.py: one chromosome carries two expressions, and the loss sets one objective per expression. Here the expressions are the right-hand sides of the Lotka-Volterra system\n\nfracdxdt = x - x y qquad fracdydt = x y - y\n\nsplit_karva(elem, 2) splits the four genes of a chromosome into f (for dx/dt) and g (for dy/dt), split_predict(elem, ctx, 2) evaluates both in a buffer context, and split_equations(elem, 2) prints them. The loss integrates each equation with the other state read from the data – f with the simulated x and the measured y, g with the measured x and the simulated y – so the error of x judges f alone and the error of y judges g alone.\n\nusing GeneExpressionProgramming\nusing Random\nusing Statistics\n\nRandom.seed!(1)\n\n# the data: six trajectories, sampled every 0.1 up to t = 8\nx0 = [0.5, 1.5, 2.0, 1.0, 0.8, 0.3]\ny0 = [1.0, 0.5, 1.5, 2.0, 0.3, 0.8]\nn = length(x0)\ndt, steps, every = 0.01, 800, 10\n\n# RK4 for the pair (x, y), sampled every `every` steps; `rhs(x, y, k)` also gets the time\n# of the stage in half steps, k dt/2, at which the loss reads the measured states\nfunction rk4(rhs, x0, y0, dt, steps, every)\n    x, y = copy(x0), copy(y0)\n    xs, ys = zeros(length(x0), steps ÷ every), zeros(length(y0), steps ÷ every)\n    for s in 0:steps-1\n        k1x, k1y = rhs(x, y, 2s)\n        k2x, k2y = rhs(x .+ 0.5dt .* k1x, y .+ 0.5dt .* k1y, 2s + 1)\n        k3x, k3y = rhs(x .+ 0.5dt .* k2x, y .+ 0.5dt .* k2y, 2s + 1)\n        k4x, k4y = rhs(x .+ dt .* k3x, y .+ dt .* k3y, 2s + 2)\n        x = x .+ dt / 6 .* (k1x .+ 2 .* k2x .+ 2 .* k3x .+ k4x)\n        y = y .+ dt / 6 .* (k1y .+ 2 .* k2y .+ 2 .* k3y .+ k4y)\n        # a candidate that blows up is not worth integrating to the end\n        (all(isfinite, x) && all(isfinite, y) && maximum(abs, x) < 1e6 && maximum(abs, y) < 1e6) ||\n            return nothing\n        if (s + 1) % every == 0\n            xs[:, (s+1)÷every] .= x\n            ys[:, (s+1)÷every] .= y\n        end\n    end\n    return xs, ys\nend\n\nlotka_volterra(x, y, _) = (x .- x .* y, x .* y .- y)\nx_data, y_data = rk4(lotka_volterra, x0, y0, dt, steps, every)\n# the measured states at every half step, from a run at half the step: column k + 1 holds\n# the time k dt/2\nx_half, y_half = rk4(lotka_volterra, x0, y0, dt / 2, 2steps, 1)\nx_measured, y_measured = hcat(x0, x_half), hcat(y0, y_half)\n\nregressor = GepRegressor(2; entered_features=[:x, :y], entered_non_terminals=[:+, :-, :*],\n    gene_connections=[:+, :-, :*], gene_count=4, head_len=4, number_of_objectives=2)\n\n# one buffer context per thread with two sets of states side by side, (x, measured y) for\n# f and (measured x, y) for g: one split_predict evaluates both expressions\nctxs = thread_contexts(regressor.toolbox_, zeros(2, 2n))\nfeature(i) = only(k for (k, nd) in regressor.toolbox_.nodes if nd isa InputSelector && nd.idx == i)\nx_sym, y_sym = feature(1), feature(2)\n\nfunction loss(elem, validate::Bool)\n    isnan(mean(elem.fitness)) || validate || return\n    local ctx = ctxs[Threads.threadid()]\n    local xs, ys = ctx.nodes[x_sym], ctx.nodes[y_sym]\n    function rhs(x, y, k)\n        xs[1:n] .= x\n        ys[1:n] .= @view y_measured[:, k+1]\n        xs[n+1:2n] .= @view x_measured[:, k+1]\n        ys[n+1:2n] .= y\n        local f, g = split_predict(elem, ctx, 2)\n        (f isa AbstractVector && g isa AbstractVector) || return (fill(NaN, n), fill(NaN, n))\n        return f[1:n], g[n+1:2n]\n    end\n    local sim = rk4(rhs, x0, y0, dt, steps, every)\n    elem.fitness = isnothing(sim) ? (Inf, Inf) :\n                   (mean(abs2, sim[1] .- x_data), mean(abs2, sim[2] .- y_data))\nend\n\n# the probe states: 36 of the (x, y) states the trajectories visit\nstates = vcat(vec(x_data)', vec(y_data)')\nprobes = states[:, randperm(size(states, 2))[1:36]]\nsurrogate = SurrogateScreening(regressor, probes;\n    expressions=2,                  # one latent block per expression\n    objective_expressions=[1, 2],   # the error of x judges f alone, that of y judges g\n    individuals_per_epoch=0.15,\n    seed=1)\n\n# only what the solver has scored may stop the search, never a prediction\nsolved(population, epoch) =\n    any(c -> is_validated(surrogate, c) && maximum(c.fitness) < 1e-10, population)\n\nfit!(regressor, 100, 200, loss; surrogate=surrogate, hof=10, break_condition=solved)\n\n# the front: the non-dominated members of the hall of fame, which the solver has all\n# scored; an error below 1e-10 is round-off and counts as solved\nbest = regressor.best_models_\nfront = best[calculate_fronts([max.(m.fitness, 1e-10) for m in best])[1]]\nfor m in unique(m -> m.fitness, front)\n    f, g = split_equations(m, 2)\n    println(m.fitness, \"   dx/dt = \", f, \"   dy/dt = \", g)\nend\n\nWhat changes against a single objective:\n\nexpressions = 2 embeds a chromosome with one latent block per expression: each part split_karva makes, evaluated on the probes. The whole karva string joins the parts with connectors the loss never uses, so its behaviour is not what the loss sees. The gene count has to be divisible by the number of expressions.\nobjective_expressions = [1, 2] lets the process of each objective see the block of the expression it judges alone; the other block would only blur its distances. On this system, the rank correlation of predictions and held-out losses went from -0.21, 0.35, 0.18 and 0.29 to 0.19, 0.35, 0.54 and 0.56 in two runs, and the screened search solved both equations on 5 of 6 seeds instead of 2. An objective that depends on all expressions takes 0 or :all.\nThe pick scalarizes the objectives by a random augmented Chebyshev weighting per epoch (ParEGO); screen = GpScreen(acquisition = :ehvi) ranks by the expected hypervolume improvement instead.\nThe break condition asks is_validated(surrogate, c), so that only a loss value, never a prediction, can stop the search.\nThe result is a front, not one model: best_models_ holds the hof best models by the mean of their objectives, all of them scored by the loss (validate_hof), and calculate_fronts picks the non-dominated ones. A large hof costs a loss call per predicted member at the end.\n\nexamples/Main_surrogate_multi_objective.jl runs this search with and without the screening, and prints every tenth epoch the best scored errors and why the solver calls of that epoch were made. With its seed, the screened search solves both equations at epoch 54 after 1,196 solver calls, the search without screening at epoch 73 after 10,168. Over seeds 1 to 6 (with other probe states), the screened search solved five, after 800 to 2,050 solver calls; over seeds 1 to 3, the search without screening solved two, after 8,850 and 10,170.\n\nIntegrating each equation against the measured other state is what makes one objective judge one expression. Integrated as a coupled system, both errors depend on both expressions, and neither the screened search nor the one without screening solved the system reliably in 100 epochs."},{"title":"Objectives Known Without the Loss","page":"Surrogate Screening","location":"examples/surrogate-screening.html#Objectives-Known-Without-the-Loss","category":"section","text":"An objective the loss computes from the chromosome alone, such as the size of the model, is better computed than predicted: a Gaussian process cannot tell the size of an expression from its behaviour. exact_objectives maps such an objective to its function; every predicted individual receives its exact value, and the acquisition sees it without uncertainty. The function has to return exactly what the loss sets:\n\nsize_of(c) = 0.01 * length(c.expression_raw)\n\n# the loss sets (error of x, error of y, size_of(elem)); the regressor has\n# number_of_objectives=3\nsurrogate = SurrogateScreening(regressor, probes;\n    expressions=2,\n    objective_expressions=[1, 2, :all],   # the size depends on both expressions\n    exact_objectives=Dict(3 => size_of))  # computed, not predicted"},{"title":"What the Screening Guarantees","page":"Surrogate Screening","location":"examples/surrogate-screening.html#What-the-Screening-Guarantees","category":"section","text":"A prediction is never cached. A copy of a predicted individual is screened again, while a copy of a scored one takes its loss times penalty, even once the fitness cache has dropped it.\nNo prediction claims a best loss. A prediction is at least one float step worse than the best loss scored so far on every objective, so it cannot beat, tie or dominate the individual holding one.\nThe best individual of an epoch is scored before its loss is recorded, selected with or shown to break_condition, and the returned hall of fame is scored at the end (validate_hof = true). Every member of best_models_ carries a loss value: is_validated(surrogate, m) is true.\nWith several objectives, a prediction is provisional. The individuals that carry one are screened again every epoch, next to the new ones, so that a later process can pick them for a loss call or give them a fresh prediction (rescreen). Without, the population fills up with stale predictions: in a search for an ODE system, 197 of 200 survivors carried one after 50 epochs, while the best scored losses had not moved since epoch 10. With one objective re-screening was a wash on the benchmark below, and it is off unless rescreen = true.\nWith several objectives, the scored holders of the best values survive. The population survives by the mean of its objectives, which a prediction can beat without dominating anyone. The scored individuals that hold the best value of an objective are therefore kept right behind the leader, and the best scored value of every objective among the survivors never gets worse.\nOnly a screened search is affected. fit! without surrogate scores every new individual, as it always does.\n\nIn your own callbacks (a break_condition, a file_logger_callback), is_validated(surrogate, c) tells a loss value from a prediction."},{"title":"Settings Worth Knowing","page":"Surrogate Screening","location":"examples/surrogate-screening.html#Settings-Worth-Knowing","category":"section","text":"Keyword Default What it does\nindividuals_per_epoch 10 individuals the loss scores per screened epoch: a count, or a share in (0, 1) of the new individuals\nembedding :expression :genes embeds one block per gene (GeneEmbedder), for a loss that scores the least-squares combination of the genes (linear_scaling)\nexpressions 1 latent blocks per chromosome, one per expression of a multi-expression loss\nobjective_expressions nothing the expression each objective judges, one entry per objective (0 or :all for all of them)\nexact_objectives nothing objectives computed from the chromosome instead of predicted, as objective => function\nscreen GpScreen() the ranking: acquisition = :lcb (default), :logei, :logei_believer, :ehvi; kappa, fit\nbudget_rule :fixed :uncertainty scores only the individuals whose optimistic bound still beats the incumbent: a gain with several objectives, a collapse with one, as the Python package measured\ntarget_transform :log10 :asinh or :none for objectives that can be negative\nwarmup_runs, warmup_batch six times the batch (at least 60), twice the batch (at least 20) the warmup before the processes take over\noffspring_multiplier nothing children bred per child the population takes, the processes picking which enter; by default 3 from 10 individuals per epoch on, else 1\nrescreen nothing screen the predictions again every epoch; nothing does so with several objectives only\nseed 0 the random choices of the screening\n\nFor a GepTensorRegressor, SurrogateScreening(regressor, probes; components=3) embeds with a TensorEmbedder on probe columns like those given to allocate_buffers!, components being the numbers per sample of an output (here a vector of 3); with several expressions, one number for all of them or one per expression. Any function chromosome -> latent vector (or nothing) works as an embedder: SurrogateScreening(embedder; ...). Surrogate Screening in the API reference lists every option."},{"title":"Diagnostics","page":"Surrogate Screening","location":"examples/surrogate-screening.html#Diagnostics","category":"section","text":"surrogate.evaluated_count: loss calls made through the screening; surrogate.imputed_count: predictions handed out instead\nsurrogate.broken_count: individuals scored as a crash because they could not be embedded; surrogate.failed_count: loss calls that returned a non-finite value (from 5 on, a model of which individuals the loss can score gates the batch)\nsurrogate.spearman_log: the rank correlation of prediction and loss within each screened batch, of the first predicted objective; surrogate.spearman_objectives holds one such log per objective. A batch holds the individuals the processes rated most promising, which are hard to tell apart, so the values are low even where the screening works; follow them over the run rather than reading single ones\nsurrogate.last_batch: the individuals the loss scored in the last epoch, as (chromosome, fitness, reason), the reason being :warmup, :acquisition, :explore or :validation\narchive_size(surrogate): individuals scored with a finite loss\n\nA file_logger_callback sees every epoch after the screening, for instance to report where the loss calls went:\n\nfunction report(population, epoch, _)\n    epoch % 10 == 0 || return\n    reasons = [entry.reason for entry in surrogate.last_batch]\n    println(\"epoch \", epoch, \": \", length(reasons), \" loss calls (\",\n        join((\"$(count(==(r), reasons)) $r\" for r in unique(reasons)), \", \"), \"), \",\n        count(c -> !is_validated(surrogate, c), population), \" individuals without a loss\")\nend\n\nfit!(regressor, 100, 200, loss; surrogate=surrogate, file_logger_callback=report)"},{"title":"Saving and Continuing","page":"Surrogate Screening","location":"examples/surrogate-screening.html#Saving-and-Continuing","category":"section","text":"The screening is the memory of a search: every individual the loss has scored, with its latent vector and loss. Use a fresh one for every search. Passing the same one again continues from what it has learned, e.g. with a load_state_callback, and it can be saved alongside the population:\n\nusing Serialization\n\nserialize(\"screening.jls\", surrogate)\nsurrogate = deserialize(\"screening.jls\")"},{"title":"When the Screening Pays Off","page":"Surrogate Screening","location":"examples/surrogate-screening.html#When-the-Screening-Pays-Off","category":"section","text":"Fitting the processes and ranking the new individuals costs time of its own, which grows with the archive of scored individuals (at most 1000) and with the objectives. Measured on one thread, outside the loss:\n\nsearch without screening screened\nthe ODE above, a batch of 10 0.009 s per epoch 0.035 s per epoch\nthe ODE above, 15 % of the new individuals 0.009 s per epoch 0.11 s per epoch\nthe system of two ODEs, 15 % 0.011 s per epoch 0.19 s per epoch\n\nThe screening saves time where a loss call costs more than that over the individuals it spares: a solver, a simulation, an external program. With a cheap loss it works too, but the time goes into the processes instead.\n\nOn three benchmark functions (10 seeds each, 200 individuals, 40 epochs, a custom MSE loss; benchmark/surrogate_screening.jl), screening 15 % of the new individuals beat scoring every individual at about 6.5 times fewer loss calls, and a batch of 10 per epoch beat a search without screening at the same number of loss calls on every function. Median MSE of the returned model:\n\n loss calls x_1^2 + x_1 x_2 - 2x_2^2 Nguyen-4 Nguyen-7\nevery individual scored 5,165-5,681 7.9e-2 (1 exact) 2.1e-2 1.0e-3\nscreened, 15 % of the new individuals 751-876 7.4e-3 (5 exact) 8.1e-3 8.9e-4\nscreened, 10 per epoch 438-472 9.4e-2 (1 exact) 1.4e-2 3.4e-3\nno screening, population 30, 20 epochs 415-429 2.9e-1 9.9e-2 7.8e-3\n\n(exact: MSE below 1e-10, of 10 seeds.)\n\nA screened search is still an evolutionary search: it can settle in a local optimum like any other. Of the six seeds of the system above, one found dy/dt but settled at dx/dt ≈ 1 - y, with an error of x of 0.04."},{"title":"The Constants of a Model","page":"Surrogate Screening","location":"examples/surrogate-screening.html#The-Constants-of-a-Model","category":"section","text":"A Gaussian process screens the constants of a model just as well: fit!(...; constant_optimizer=ScreenedNelderMead()) tunes the constants of the best model against the loss, with the loss calls placed by a process over the constants, and optimize_constants! and simplex_search do so on their own. Coefficient Tuning shows when to use which variant, what to do about runs that diverge, and a closure model searched with a fictive CFD solver in the loop."},{"title":"Running the Examples","page":"Surrogate Screening","location":"examples/surrogate-screening.html#Running-the-Examples","category":"section","text":"From a clone of the repository:\n\njulia --project=. --threads=4 examples/Main_surrogate_screening.jl\njulia --project=. --threads=4 examples/Main_surrogate_multi_objective.jl\n\nEach runs its search with and without the screening and reports the solver calls; the first search of a session includes the compilation.\n\n\n\nContinue to Coefficient Tuning, or to the API Reference for every option."},{"title":"GeneExpressionProgramming.jl Documentation","page":"Home","location":"index.html#GeneExpressionProgramming.jl-Documentation","category":"section","text":"GeneExpressionProgramming.jl is a Julia package for symbolic regression by Gene Expression Programming (GEP): it evolves explicit equations that fit data."},{"title":"Features","page":"Home","location":"index.html#Features","category":"section","text":"Gene Expression Programming: a model is a chromosome of Int8 tokens – genes, each a head and a tail, joined by connectors. Its karva string is scored by a batched evaluator that applies every operator to whole data columns, in buffers allocated once per thread.\nMulti-objective optimisation: a custom loss can score several objectives (accuracy, size, ...); parents are then selected by NSGA-II.\nPhysical dimensions: given the SI dimensions of the features and of the target, semantic backpropagation (SBP) repairs candidates towards the target dimension, and only homogeneous candidates are scored.\nTensor regression: scalar, vector and tensor features (Tensors.jl) side by side, through the same batched evaluator.\nConstant optimisation and linear scaling (fit! on data): Nelder-Mead tuning of the constants of the best model, or one least-squares coefficient per gene.\nSurrogate screening of expensive losses: Gaussian processes over the behaviour of the candidates decide which few individuals per epoch the loss scores, and predict the loss of the others (SurrogateScreening), for one or several objectives and for chromosomes that carry several expressions.\nConstants against an expensive loss: Nelder-Mead whose loss calls a Gaussian process over the constants places where it expects the minimum (ScreenedNelderMead), after a screened particle swarm in a box for a loss with several minima (swarm_box), for the constants of the best model inside a search (constant_optimizer of fit!) or on their own (optimize_constants!, simplex_search), e.g. with a CFD simulation as the cost function.\nThreads: fitness evaluation, genetic operators and repair run on the threads Julia is started with (julia --threads=auto)."},{"title":"Quick Start","page":"Home","location":"index.html#Quick-Start","category":"section","text":"using Pkg\nPkg.add(url=\"https://github.com/maxreiss123/GeneExpressionProgramming.jl.git\")\n\nusing GeneExpressionProgramming\nusing Random\n\n# Generate sample data\nRandom.seed!(42)\nx_data = randn(100, 2)\ny_data = @. x_data[:,1]^2 + x_data[:,2]\n\n# Create and train regressor\nregressor = GepRegressor(2)\nfit!(regressor, 1000, 1000, x_data', y_data; loss_fun=\"mse\")\n\n# View the discovered expression\nprintln(regressor.best_models_[1])\n# e.g. ((x1 * x1) + x2) -- the exact form varies from run to run"},{"title":"Documentation Structure","page":"Home","location":"index.html#Documentation-Structure","category":"section","text":"Installation: install the package and start Julia with threads\nGetting Started: a first symbolic regression, step by step\nCore Concepts: chromosomes, genetic operators, selection, dimensions and the evaluator\nAPI Reference: functions, types and keyword arguments\nExamples:\nBasic Regression: the complete workflow on a known function\nMulti-Objective Optimization: accuracy against expression size\nPhysical Dimensionality: a search held to physical units\nTensor Regression: a vector-valued target from scalar and vector features\nSurrogate Screening: expensive losses (a solver in the loop), with one objective and with several expressions and objectives\nCoefficient Tuning: the constants of a model against an expensive loss, inside a search and on their own, and a closure model searched with a fictive CFD solver in the loop"},{"title":"Research Foundation","page":"Home","location":"index.html#Research-Foundation","category":"section","text":"The package implements the constraint of genetic symbolic regression by semantic backpropagation described in:\n\nReissmann, M., Fang, Y., Ooi, A. S. H., & Sandberg, R. D. (2025). Constraining genetic symbolic regression via semantic backpropagation. Genetic Programming and Evolvable Machines, 26(1), 12.\n\nIt builds on concepts explored and developed in:\n\nFerreira, C. (2001). Gene Expression Programming: a New Adaptive Algorithm for Solving Problems. Complex Systems, 13.\n\nK. Deb, A. Pratap, S. Agarwal and T. Meyarivan, (2002) \"A fast and elitist multiobjective genetic algorithm: NSGA-II,\" in IEEE Transactions on Evolutionary Computation, vol. 6, no. 2, pp. 182-197 \n\nWeatheritt, J., Sandberg, R. D. (2016)  A novel evolutionary algorithm applied to algebraic modifications of the RANS stress–strain relationship. Journal of Computational Physics, vol. 325, pp. 22-37\n\nWaschkowski, F., Zhao, Y., Sandberg R. D., Klewicki J., (2022), Multi-objective CFD-driven development of coupled turbulence closure models. Journal of Computational Physics, vol. 452, \n\nFang, Y., Waschkowski, F., Reissmann, M., Sandberg, R. D., Oda, T., & Tanimoto, K. (2025). A surrogate-augmented symbolic CFD-driven training framework for accelerating multi-objective physical model development. arXiv. https://arxiv.org/abs/2512.19031"},{"title":"Community and Support","page":"Home","location":"index.html#Community-and-Support","category":"section","text":"Report bugs, request features and ask questions on the GitHub repository. Contributions – fixes, features, documentation and examples – are welcome."},{"title":"Citation","page":"Home","location":"index.html#Citation","category":"section","text":"If you use GeneExpressionProgramming.jl in your research, please cite:\n\n@article{Reissmann2025,\n  author   = {Maximilian Reissmann and Yuan Fang and Andrew S. H. Ooi and Richard D. Sandberg},\n  title    = {Constraining Genetic Symbolic Regression via Semantic Backpropagation},\n  journal  = {Genetic Programming and Evolvable Machines},\n  year     = {2025},\n  volume   = {26},\n  number   = {1},\n  pages    = {12},\n  doi      = {10.1007/s10710-025-09510-z},\n  url      = {https://doi.org/10.1007/s10710-025-09510-z}\n}"},{"title":"Version Information","page":"Home","location":"index.html#Version-Information","category":"section","text":"These pages describe the current code in the GitHub repository, which may be ahead of the latest registered release."},{"title":"Acknowledgement","page":"Home","location":"index.html#Acknowledgement","category":"section","text":"Tensor-valued features and operations build on Tensors.jl.\nEarlier versions evaluated expressions with DynamicExpressions.jl; the current evaluator is a batched stack machine written for this package.\n\n"},{"title":"Core Concepts","page":"Core Concepts","location":"core-concepts.html#Core-Concepts","category":"section","text":"This chapter describes how GeneExpressionProgramming.jl represents, evaluates and evolves models, and what its settings control."},{"title":"Gene Expression Programming Fundamentals","page":"Core Concepts","location":"core-concepts.html#Gene-Expression-Programming-Fundamentals","category":"section","text":""},{"title":"Background","page":"Core Concepts","location":"core-concepts.html#Background","category":"section","text":"Gene Expression Programming (GEP) was introduced by Cândida Ferreira in 2001 as an evolutionary algorithm that combines ideas of genetic algorithms and genetic programming [1]. It separates the genotype, a fixed-length linear chromosome, from the phenotype, the expression the chromosome encodes, whose size and shape vary. The genetic operators edit the linear chromosome and, except for the fusion operators (off by default), keep every symbol valid for its position, so every chromosome encodes a valid expression."},{"title":"Chromosomes and Genes","page":"Core Concepts","location":"core-concepts.html#Chromosomes-and-Genes","category":"section","text":"A chromosome is a vector of Int8 symbols, laid out as:\n\nConnectors: gene_count - 1 binary functions (from gene_connections) that join the genes\nGenes: gene_count genes, each a head of head_len symbols (functions and terminals) and a tail of head_len + 1 symbols (terminals only)\nPreamble: optionally gene_count further terminals (preamble_syms), outside the expression\n\nThe tail length follows GEP's rule t = h × (n − 1) + 1 for head length h and maximum arity n; all functions here have arity 1 or 2, so t = h + 1. Even a head of binary functions then finds enough terminals in the tail, so every gene encodes a complete expression."},{"title":"Translation","page":"Core Concepts","location":"core-concepts.html#Translation","category":"section","text":"Each gene is read from left to right in prefix order (depth-first, as in prefix GEP), rather than Ferreira's breadth-first K-expression: a function takes the subexpressions that follow it as its operands, and reading stops once every function has its operands. The symbols read form the gene's active part; the rest of the gene is inactive until a change in the head extends the active part. Prefix order keeps every subexpression contiguous in the gene, which is what lets the unit repair replace a subexpression in place.\n\nThe connectors, followed by the active part of each gene, form the chromosome's karva string (expression_raw), which is what the evaluator runs. A chromosome with genes G1, G2, G3 and connectors c1, c2 encodes c1(c2(G1, G2), G3)."},{"title":"Evaluation","page":"Core Concepts","location":"core-concepts.html#Evaluation","category":"section","text":"GeneExpressionProgramming.jl never builds an expression tree. The batched evaluator walks the karva string as a stack machine, from right to left, and applies every operator to whole data columns at once, writing into buffers allocated once per thread. When all terminals and intermediate values share one type, as in scalar regression, the alphabet is compiled into a monomorphic program (compile_program, run_program!) that avoids dynamic dispatch; otherwise calc_stack_batch_tensor evaluates with dynamic dispatch."},{"title":"Evolutionary Operators","page":"Core Concepts","location":"core-concepts.html#Evolutionary-Operators","category":"section","text":""},{"title":"Selection","page":"Core Concepts","location":"core-concepts.html#Selection","category":"section","text":"Tournament selection is used for a single objective: each parent is the best of k contenders drawn at random, with replacement. Only individuals with a finite fitness take part, and individuals with identical fitness count once; if no fitness is finite, the whole population takes part. The best individual is always among the parents. Larger tournaments raise the selection pressure; fit! uses 3 % of the population for GepRegressor and 0.3 % for GepTensorRegressor, at least 3.\n\nNSGA-II is used with more than one objective (a fitness tuple of more than one entry, as number_of_objectives > 1 sets up): the population is sorted into Pareto fronts, and parents are chosen by tournaments of 3 that prefer the lower front and, within a front, the larger crowding distance. There is no finiteness filter here; instead, a fitness tuple with more non-finite entries (Inf, NaN) is ranked behind one with fewer (dominates_)."},{"title":"Genetic Operators","page":"Core Concepts","location":"core-concepts.html#Genetic-Operators","category":"section","text":"All operators edit the linear chromosome. Their probabilities and rates are the entries of RegressionWrapper.GENE_COMMON_PROBS (defaults in the API Reference). Crossover and fusion act on a pair of parents; the other operators act on each offspring with its own draw.\n\nCrossover between two parents:\n\nOne-point crossover (one_point_cross_over_prob): in every gene, each offspring keeps one random segment of its own symbols, from a position among the gene's first head_len + 1 to one among its last head_len, and takes all other symbols (connectors and preamble included) from the other parent\nTwo-point crossover (two_point_cross_over_prob): the same with other segments: one offspring keeps two segments of each gene, the other a random suffix of each gene\nFusion operators (dominant_fusion_prob, rezessiv_fusion_prob, fusion_prob): at randomly drawn positions, an offspring takes the larger, the smaller or the mean of the two parents' symbol ids, which need not be valid there (off by default)\n\nMutation and rearrangement:\n\nPoint mutation (mutation_prob, mutation_rate): round(mutation_rate × length) positions, drawn with replacement, take the symbol at the same position of a freshly generated chromosome, so each keeps a symbol valid for its place (connector, head or tail)\nInversion (inversion_prob): reverses a run of head symbols. As implemented, it reverses positions gene_count to head_len of the chromosome – part of the first gene's head – when the first gene is drawn, and nothing otherwise\nInsertion (insertion_prob): writes a random terminal into a random head position\nRoot insertion (root_insertion_prob): rotates a gene's head by a random offset, so another head symbol becomes the gene's root\nTail rotation (reverse_insertion_tail): rotates a gene's tail, without its first symbol, by a random offset (off by default)\nGene transposition (gene_transposition_prob): swaps two segments of min(5, head_len + 1) symbols between the tails of two genes, possibly the same gene\n\nGene averaging (gene_averaging_prob, gene_averaging_rate, gene_averaging_elite_frac): pulls an offspring towards the consensus of an elite: the best-ranked individuals, gene_averaging_elite_frac times the mating size in number (at least 3). The consensus draws, per position, one of the three symbols most frequent there among the elite, with probability proportional to its count, and each position of the offspring takes it with probability gene_averaging_rate."},{"title":"Population Dynamics","page":"Core Concepts","location":"core-concepts.html#Population-Dynamics","category":"section","text":"Each epoch, m offspring are bred, m being ceil(mating_size × population_size) (mating_size is 0.7 by default), less one if odd. The population holds population_size + m individuals, ranked by the mean of their fitness tuples. The offspring take ranks population_size - m to population_size - 1; the individuals they displace move behind the first population_size, where they are neither scored nor selected but are ranked again in the next epoch, and those previously there are dropped. The best population_size - m - 1 individuals thus survive unchanged (elitism).\n\nDuplicate penalty: fitness is cached by karva string in an LRU cache of 10,000 entries. A new individual whose karva string is cached, or already queued for scoring in the same epoch, is not evaluated (unless its entry has been evicted): it gets the cached fitness multiplied by penalty (fit!, 2.0 by default). For a non-negative loss this keeps copies of one solution from taking over the population; with a loss that can be negative, a penalty above 1 favours them."},{"title":"Multi-Objective Optimization","page":"Core Concepts","location":"core-concepts.html#Multi-Objective-Optimization","category":"section","text":""},{"title":"Pareto Optimality","page":"Core Concepts","location":"core-concepts.html#Pareto-Optimality","category":"section","text":"For symbolic regression, typical objectives are the prediction error and the size of the expression. A solution dominates another if it is no worse in every objective and better in at least one; the Pareto-optimal solutions are those no other solution dominates. NSGA-II selects parents by Pareto rank."},{"title":"Crowding Distance","page":"Core Concepts","location":"core-concepts.html#Crowding-Distance","category":"section","text":"Within a front, NSGA-II prefers individuals in less crowded regions of the objective space, measured per objective relative to the front's range, so the search spreads along the front instead of converging to one region."},{"title":"Ranking by the Mean","page":"Core Concepts","location":"core-concepts.html#Ranking-by-the-Mean","category":"section","text":"Survival and the hall of fame (best_models_) use the population ranked by the mean of each fitness tuple, not by Pareto rank. Objectives on very different scales therefore let the larger one dominate that ranking; bring them to comparable scales, and pick the non-dominated models out of best_models_ with dominates_ (see Multi-Objective Optimization)."},{"title":"Physical Dimensionality and Semantic Backpropagation","page":"Core Concepts","location":"core-concepts.html#Physical-Dimensionality-and-Semantic-Backpropagation","category":"section","text":""},{"title":"Dimensional Analysis","page":"Core Concepts","location":"core-concepts.html#Dimensional-Analysis","category":"section","text":"Semantic backpropagation (SBP) [2] holds evolved expressions to physical units.\n\nDimensional representation: a dimension is a vector of SI exponents, in the order [kg, m, s, K, mol, A, cd] – mass, length, time, temperature, amount of substance, electric current, luminous intensity (the order OpenFOAM uses). Velocity is Float16[0, 1, -1, 0, 0, 0, 0]. On the tensor path the vector carries the tensor order in front of the SI exponents.\n\nForward propagation: the dimension of an expression is computed bottom-up from the dimensions of its terminals, following the rules of dimensional analysis:\n\nAddition, subtraction, min, max: the operands must have the same dimension\nMultiplication: dimensions are added\nDivision: dimensions are subtracted\nSquare root: dimensions are halved; sqr doubles them\nTranscendental functions (exp, log, sin, ...): the argument must be dimensionless, and so is the result\nabs, floor, ceil, round, sign: the dimension is kept\nPower ^: only between dimensionless operands (use sqr and sqrt for dimensioned ones)\n\nAn expression that breaks a rule is inconsistent; it is homogeneous when its dimension equals the target's.\n\nBackward propagation: the rules also run top-down: given the dimension a node must have, they give the dimensions its operands must have (for a product, one operand's requirement follows from the other's dimension). This is what lets a requirement be pushed from the root of an expression to the subexpression that violates it."},{"title":"The Library","page":"Core Concepts","location":"core-concepts.html#The-Library","category":"section","text":"A regressor built with considered_dimensions builds a library of dimensionally consistent subexpressions from the features, the non-zero constants and the functions: each of rounds rounds extends the expressions by one symbol and keeps at most max_permutations_lib new ones, so library expressions have up to rounds + 1 symbols. The library is indexed by dimension: an exact lookup for its own dimensions, and a kd-tree over those and the dimensions one more operator reaches from them (a product or quotient of two library expressions, on the scalar path, or a unary function of one)."},{"title":"Repair During the Search","page":"Core Concepts","location":"core-concepts.html#Repair-During-the-Search","category":"section","text":"With a target dimension (fit!(...; target_dimension=...)), every epoch runs two passes before the new individuals are scored:\n\nCheck: every new individual gets the forward check, in parallel. Individuals born homogeneous are flagged and need nothing else.\nRepair: the others are repaired in place (correct_genes!), every correction_epochs epochs and at most correction_amount times the population size of them. The target is pushed down the expression; at each node the cheapest fix that meets the requirement is taken – swapping a terminal or an operator for one of the right dimension, dropping a unary function, splitting the requirement between the operands of a binary node, or replacing the subexpression with one of the needed dimension from the library. A repair only writes what the genetic operators could have written: operators stay in a gene's head, genes stay within their length, and connectors are only swapped for other connectors. A repaired individual is flagged only once its recompiled expression passes the check of step 1.\n\nOnly homogeneous individuals are scored; an individual that is neither born homogeneous nor repaired gets the worst fitness (Inf). Part of the initial population (lib_seed_amount, half by default) is seeded with library expressions: if some connectors keep the dimension of their operands (+, -, min, max), the seeded genes all take the target dimension and are joined by those; otherwise the first gene takes it and the others are dimensionless. An individual is seeded only if the library can fill each of its genes.\n\nSince nearly every offspring passes the repair, neutral variants of the current best – the same predictions from a different karva string, such as a model multiplied by zero – could fill the population. Under a target, individuals whose fitness exactly repeats that of a better-ranked one are therefore ranked behind all distinct individuals when the survivors are chosen.\n\nWith linear_scaling=true the model is the weighted sum of its genes, whose coefficients are dimensionless only if every gene has the target dimension. The check and the repair then go gene by gene (is_gene_wise_homogeneous, correct_genes! with gene_wise=true), and with + or - among the connectors the connected expression takes the target too. A custom loss that scores the genes' least-squares combination (predictT_scaled) asks for the same with gene_wise_dimension=true."},{"title":"Tensor Operations and Advanced Data Types","page":"Core Concepts","location":"core-concepts.html#Tensor-Operations-and-Advanced-Data-Types","category":"section","text":""},{"title":"Tensor Regression","page":"Core Concepts","location":"core-concepts.html#Tensor-Regression","category":"section","text":"For problems involving vector or tensor data, GepTensorRegressor evolves expressions over columns of scalars and Tensors.jl vectors and tensors side by side; problem_dimension sets the spatial dimension of the tensors. Besides the scalar functions it offers:\n\nProducts: * (products with a scalar), dot (single contraction), dcontract (double contraction), otimes (outer product), crossp (cross product of 3D vectors), hadamard (element-wise product)\n\nInvariants and norms: tr (trace), det (determinant), norm\n\nParts and derived tensors: symmetric, skew, dev (deviatoric part), vol (volumetric part), inv (inverse), tdot and dott (both A·Aᵀ), lap (contraction of a third-order tensor with the identity)\n\nA chromosome that combines operands of incompatible orders cannot be evaluated (the evaluator returns NaN, a column of Inf, or throws); the loss callback gives it a penalty (see Tensor Regression). The dimension vectors of the tensor path carry the tensor order in front of the SI exponents. With considered_dimensions, only the functions that have tensor unit rules can be entered (any other makes the constructor throw): +, -, *, /, inv, dot, crossp, tr, det, dcontract, lap, hadamard, sqrt, norm, log, exp, sin and cos."},{"title":"Performance Considerations","page":"Core Concepts","location":"core-concepts.html#Performance-Considerations","category":"section","text":"Tensor operations cost more than scalar ones. The evaluator applies every operator to a whole column of samples at once, into buffers allocated once per thread and per tensor type (allocate_buffers!), so evaluating a candidate does not allocate arrays the size of the data. GPU evaluation is not implemented."},{"title":"Loss Functions and Fitness Evaluation","page":"Core Concepts","location":"core-concepts.html#Loss-Functions-and-Fitness-Evaluation","category":"section","text":""},{"title":"Standard Loss Functions","page":"Core Concepts","location":"core-concepts.html#Standard-Loss-Functions","category":"section","text":"Losses are selected by name (fit!(...; loss_fun=\"mse\"), or get_loss_function(name)):\n\n\"mse\" Mean Squared Error\n\"mae\" Mean Absolute Error: less sensitive to outliers\n\"rmse\" Root Mean Squared Error: in the units of the target\n\"nrmse\" RMSE divided by the standard deviation of the target, and \"srsme\", a relative RMSE (each residual divided by the magnitude of the target)\n\"r2_score\", \"r2_score_f\" (the same, computed on data rescaled by a power of ten for very large or small magnitudes) and \"xi_core\" (a rank correlation modelled on Chatterjee's ξ): scores rather than losses, for reporting – the search minimises its loss"},{"title":"Custom Loss Functions","page":"Core Concepts","location":"core-concepts.html#Custom-Loss-Functions","category":"section","text":"Any function of the targets and the predictions that returns a number to minimise can be the loss:\n\n# regressor, x_train, y_train, epochs and population_size as in Getting Started\n# the largest absolute error\nmax_abs_error(y_true, y_pred) = maximum(abs.(y_true .- y_pred))\n\nfit!(regressor, epochs, population_size, x_train', y_train; loss_fun=max_abs_error)\n\nIn the more general form the loss receives the chromosome itself and sets its fitness, so the evaluation is up to the user: fit!(regressor, epochs, population_size, loss) with loss(elem, validate::Bool). This is the form for several objectives and for tensor regression."},{"title":"Fitness Evaluation Strategies","page":"Core Concepts","location":"core-concepts.html#Fitness-Evaluation-Strategies","category":"section","text":"Single-objective: one loss, tournament selection\n\nMulti-objective: the loss sets a tuple with one entry per objective; NSGA-II selection\n\nWeighted sum: a single-objective loss that combines several criteria with weights of your choice\n\nGene-wise linear scaling: fit!(...; linear_scaling=true) scores each chromosome as the least-squares combination of its genes, one coefficient per gene (stored in scaling_weights), so evolution searches for the structure and the coefficients are solved for. The constant optimiser does not run with it.\n\nSurrogate screening: when a loss call is expensive (a solver in the loop, a simulation), fit!(...; surrogate=SurrogateScreening(regressor, probes)) lets the loss score only a few individuals per epoch. Each new individual is embedded as the behaviour of its expression on a small probe set, a Gaussian process maps these latent vectors to the losses scored so far, and an optimistic confidence bound picks the individuals worth a loss call; the others receive the prediction of the process, never better than the best loss scored so far, and compete with it. Predictions are never cached, the best individual of every epoch and the returned models are scored by the loss, and an epoch breeds more children than the population takes so that the process can pick among them. Several objectives get one process each; a chromosome that carries several expressions (split_karva) is embedded with one block per expression (expressions = k), and objective_expressions lets the process of an objective see the block of the expression it judges alone. The example Surrogate Screening walks through both cases; the API Reference lists the options.\n\nConstants against an expensive loss: with a custom loss, fit!(...; constant_optimizer=ScreenedNelderMead()) tunes the constants of the best model against the loss every optimization_epochs epochs, by Nelder-Mead whose loss calls a Gaussian process over the constants places where it expects the minimum (screen=false for plain Nelder-Mead, with the steps of Optim.NelderMead()). optimize_constants! tunes the constants of one chromosome, simplex_search minimizes any function of a vector, e.g. the coefficients of a closure in a simulation. For a loss with several minima, swarm_box lets a particle swarm screened by a process explore a box before. The tuned values, one per occurrence of a constant, are kept in optimised_constants, which elem(ctx), split_predict and predictT(regressor, chromosome) apply. See Coefficient Tuning and the API Reference."},{"title":"Algorithm Parameters","page":"Core Concepts","location":"core-concepts.html#Algorithm-Parameters","category":"section","text":"The defaults are a starting point; no setting is best for every problem [4].\n\nParameter Where Default Effect\npopulation size, epochs fit! arguments – search effort\nhead_len GepRegressor 6 maximum size of each gene's expression\ngene_count GepRegressor 3 number of subexpressions joined by connectors\nentered_non_terminals GepRegressor [:+, :-, :*, :/] function set\nmutation_rate, crossover probabilities, ... GENE_COMMON_PROBS see API Reference variation\nmating_size GENE_COMMON_PROBS 0.7 offspring per epoch, as a fraction of the population\npenalty fit! 2.0 factor on the fitness of a duplicate\n\nLonger heads and more genes allow larger expressions at a higher evaluation cost."},{"title":"Performance","page":"Core Concepts","location":"core-concepts.html#Performance","category":"section","text":"Batched evaluation: a candidate is evaluated in one pass over its karva string, each operator applied to whole data columns; scalar alphabets run as a compiled monomorphic program.\n\nParallelism: on the threads Julia is started with, the population is generated, scored, varied and repaired in parallel, and the library is built in parallel. Scoring hands the individuals out one at a time to whichever thread is free, so uneven evaluation costs do not leave threads idle. The \"mse\" loss also splits the samples across threads from 100,000 samples on.\n\nMemory: chromosomes are vectors of Int8 symbols, and evaluation writes into buffers allocated once per thread, whose size grows with the data (see examples/Main_streaming_chunks.jl for data larger than memory).\n\nCaching: fitness is cached per karva string, so a duplicate is not evaluated again while its karva string is in the cache."},{"title":"Complexity","page":"Core Concepts","location":"core-concepts.html#Complexity","category":"section","text":"Time: evaluation usually dominates, at O(E × P × L × N) for E epochs, P individuals, karva strings of average length L and N samples. With a dimensional target, the repair adds a cost per individual that does not grow with N.\n\nSpace: O(P × S) for a population of chromosomes of S symbols, O(F × N) for F features, and O(T × g × h × N) for the evaluation buffers of T thread slots, g genes and head length h."},{"title":"Background","page":"Core Concepts","location":"core-concepts.html#Background-2","category":"section","text":"Holland's schema theorem [3] is the classical account of why selection and recombination propagate building blocks of above-average fitness; it was derived for genetic algorithms on fixed-length strings, such as GEP's chromosomes. The no-free-lunch theorems [4] state that no algorithm, and no setting of one, is best on all problems."},{"title":"References","page":"Core Concepts","location":"core-concepts.html#References","category":"section","text":"[1] Ferreira, C. (2001). Gene Expression Programming: a New Adaptive Algorithm for Solving Problems. Complex Systems, 13.\n\n[2] Reissmann, M., Fang, Y., Ooi, A. S. H., & Sandberg, R. D. (2025). Constraining genetic symbolic regression via semantic backpropagation. Genetic Programming and Evolvable Machines, 26(1), 12.\n\n[3] Holland, J. H. (1975). Adaptation in Natural and Artificial Systems: An Introductory Analysis with Applications to Biology, Control, and Artificial Intelligence. University of Michigan Press.\n\n[4] Wolpert, D. H., & Macready, W. G. (1997). No Free Lunch Theorems for Optimization. IEEE Transactions on Evolutionary Computation, 1(1), 67–82.\n\n\n\nFor the functions and keyword arguments, continue to the API Reference."},{"title":"Physical Dimensionality and Semantic Backpropagation","page":"Physical Dimensionality","location":"examples/physical-dimensions.html#Physical-Dimensionality-and-Semantic-Backpropagation","category":"section","text":"Given the physical dimensions of the features and of the target, GeneExpressionProgramming.jl holds the search to dimensionally homogeneous expressions: semantic backpropagation (SBP) repairs candidates towards the target dimension, and only homogeneous candidates are scored. Core Concepts describes the unit rules, the library and the repair."},{"title":"Understanding Physical Dimensionality","page":"Physical Dimensionality","location":"examples/physical-dimensions.html#Understanding-Physical-Dimensionality","category":"section","text":""},{"title":"Dimensional Analysis Fundamentals","page":"Physical Dimensionality","location":"examples/physical-dimensions.html#Dimensional-Analysis-Fundamentals","category":"section","text":"A physical equation must be dimensionally homogeneous: all its terms have the same physical dimension. The base dimensions of the International System of Units (SI) are:\n\nMass (M): kilogram [kg]\nLength (L): meter [m]  \nTime (T): second [s]\nTemperature (Θ): kelvin [K]\nAmount of Substance (N): mole [mol]\nElectric Current (I): ampere [A]\nLuminous Intensity (J): candela [cd]\n\nEvery physical quantity has a dimension composed of these, for example:\n\nVelocity: [L T⁻¹]\nForce: [M L T⁻²]\nEnergy: [M L² T⁻²]\nElectric Charge: [I T]"},{"title":"Dimensional Representation in GeneExpressionProgramming.jl","page":"Physical Dimensionality","location":"examples/physical-dimensions.html#Dimensional-Representation-in-GeneExpressionProgramming.jl","category":"section","text":"A dimension is a Float16 vector of SI exponents, one component per base unit, in the order listed above – [kg, m, s, K, mol, A, cd], the order OpenFOAM uses and the one the package's physical constants (get_constant_dims) are given in:\n\n# Dimension vector: [M, L, T, Θ, N, I, J]\nvelocity_dim = Float16[0, 1, -1, 0, 0, 0, 0]    # [L T⁻¹]\nforce_dim = Float16[1, 1, -2, 0, 0, 0, 0]       # [M L T⁻²]\nenergy_dim = Float16[1, 2, -2, 0, 0, 0, 0]      # [M L² T⁻²]\ncharge_dim = Float16[0, 0, 1, 0, 0, 1, 0]       # [I T]"},{"title":"Complete Physical Dimensionality Example","page":"Physical Dimensionality","location":"examples/physical-dimensions.html#Complete-Physical-Dimensionality-Example","category":"section","text":"The example recovers the electric current density in superconductivity, J = -ρqA/m (Feynman Lectures III 21.20), with ρ the charge density, q the electric charge, A the magnetic vector potential and m the mass. A shorter version is examples/Main_physical_dimensions.jl.\n\nusing GeneExpressionProgramming\nusing Random\nusing CSV\nusing DataFrames\nusing Statistics\nusing Plots\n\n# Set random seed for reproducibility\nRandom.seed!(42)\n\n# Target: the current density J, in A m⁻²\ntarget_dim = Float16[0, -2, 0, 0, 0, 1, 0]\n\n# Feature dimensions, keyed by the feature names x1 ... x4\nfeature_dims = Dict{Symbol,Vector{Float16}}(\n    :x1 => Float16[0, -3, 1, 0, 0, 1, 0],   # ρ (charge density) [A s m⁻³]\n    :x2 => Float16[0, 0, 1, 0, 0, 1, 0],    # q (electric charge) [A s]\n    :x3 => Float16[1, 1, -2, 0, 0, -1, 0],  # A (magnetic vector potential) [kg m s⁻² A⁻¹]\n    :x4 => Float16[1, 0, 0, 0, 0, 0, 0],    # m (mass) [kg]\n)\n\n# Data generated from J = -ρ * q * A / m, shipped with the repository (run from the\n# repository root); the columns are rho_c_0, q, A_vec, m and the target\ndata = Matrix(CSV.read(\"./paper/srsd/feynman-III.21.20\\$0.txt\", DataFrame))\nnum_cols = size(data, 2)\nx_train, y_train, x_test, y_test = train_test_split(data[:, 1:num_cols-1], data[:, num_cols]; consider=4)\n\n# Evolution parameters\nepochs = 1000\npopulation_size = 1000\nnum_features = num_cols - 1 \n\n# Regressor with the feature dimensions; it builds the library the repair draws on\nregressor = GepRegressor(\n    num_features;\n    considered_dimensions=feature_dims,\n    max_permutations_lib=10000,  # New library expressions kept per round\n    rounds=7                     # Library expressions have up to rounds + 1 symbols\n)\n\n# Fit with the target dimension\ntraining_time = @elapsed fit!(regressor, epochs, population_size, x_train', y_train; \n                              x_test=x_test', y_test=y_test, \n                              loss_fun=\"mse\", \n                              target_dimension=target_dim)\nprintln(\"Training completed in $(round(training_time, digits=2)) seconds\")\n\n# The best model\nbest_model = regressor.best_models_[1]\nprintln(\"Best evolved expression: \", best_model)\nprintln(\"Fitness (MSE): \", best_model.fitness[1])\nprintln(\"Dimensionally homogeneous: \",\n        is_dimensionally_homogeneous(best_model.expression_raw, target_dim, regressor.token_dto_))\n\n# Predictions and metrics\ntrain_predictions = regressor(x_train')\ntest_predictions = regressor(x_test')\n\nr2 = get_loss_function(\"r2_score\")\nfor (name, y, p) in ((\"Training\", y_train, train_predictions), (\"Test\", y_test, test_predictions))\n    println(\"$name: MSE = $(round(get_loss_function(\"mse\")(y, p), sigdigits=6)), \",\n            \"R² = $(round(r2(y, p), digits=6)), \",\n            \"max error = $(round(maximum(abs.(y .- p)), sigdigits=6))\")\nend\n\n# Comparison with the true relationship\ntrue_predictions_test = -x_test[:, 1] .* x_test[:, 2] .* x_test[:, 3] ./ x_test[:, 4]\nprintln(\"Correlation with the true relationship (test): \",\n        round(cor(true_predictions_test, test_predictions), digits=6))\n\n# Prediction accuracy and residuals\nall_y = vcat(y_train, y_test)\nall_pred = vcat(train_predictions, test_predictions)\nmin_val, max_val = extrema(vcat(all_y, all_pred))\n\np1 = scatter(y_train, train_predictions,\n             xlabel=\"Actual Current Density\", ylabel=\"Predicted Current Density\",\n             title=\"Actual vs Predicted\", alpha=0.6, label=\"Training Data\", markersize=3)\nscatter!(p1, y_test, test_predictions, alpha=0.6, color=:red, label=\"Test Data\", markersize=3)\nplot!(p1, [min_val, max_val], [min_val, max_val],\n      color=:black, linestyle=:dash, label=\"Perfect Prediction\")\n\np2 = scatter(all_pred, all_y .- all_pred,\n             xlabel=\"Predicted Values\", ylabel=\"Residuals\",\n             title=\"Residual Analysis\", alpha=0.6, legend=false, markersize=3)\nhline!(p2, [0], color=:black, linestyle=:dash)\n\nfinal_plot = plot(p1, p2, layout=(2,1), size=(800, 700))\nsavefig(final_plot, \"physical_dimensionality_analysis.png\")"},{"title":"Settings","page":"Physical Dimensionality","location":"examples/physical-dimensions.html#Settings","category":"section","text":"Feature and constant dimensions: considered_dimensions is keyed by the feature symbols (:x1, :x2, ... or the entered_features) and by the symbols of the constant terminals (Symbol(0.5), ...); unlisted features and constants, and the random constants, are dimensionless. A physical constant can enter as a terminal with its dimension, e.g. entered_terminal_nums=[Symbol(9.807)] with Symbol(9.807) => get_constant_dims(\"g\").\nLibrary: built when the regressor is constructed, from the features, the non-zero constants and the functions. rounds bounds the length of its expressions (rounds + 1 symbols) and max_permutations_lib the new expressions kept per round; larger values let the repair find more replacements, at the cost of build time and memory.\nRepair (keywords of fit!): target_dimension switches it on; correction_epochs (default 1) sets how often the repair runs, correction_amount (default 1.0) the most individuals repaired per correction epoch, as a fraction of the population, and cycles (default 10) the attempts per individual. lib_seed_amount (default 0.5) is the fraction of the initial population seeded with library expressions of the target dimension.\nLinear scaling: with linear_scaling=true the model is the weighted sum of its genes, which is homogeneous only if every gene carries the target dimension; the check and the repair therefore go gene by gene. A custom loss that scores the genes' least-squares combination (predictT_scaled) needs gene_wise_dimension=true in fit!.\nChecking a model: is_dimensionally_homogeneous(model.expression_raw, target_dim, regressor.token_dto_); dimensional_homogeneity_distance gives the distance to the target instead. For a scaled model, is_gene_wise_homogeneous(model.expression_raw, target_dim, regressor.token_dto_, gene_count) checks every gene.\n\nThe check is a cheap forward pass; the repair looks its replacements up in an index built once per regressor. If the repair still dominates the run time, lower correction_amount or raise correction_epochs; individuals that are not repaired get the worst fitness instead of being scored."},{"title":"Dimensions in Other Domains","page":"Physical Dimensionality","location":"examples/physical-dimensions.html#Dimensions-in-Other-Domains","category":"section","text":"# Fluid dynamics: pressure drop in pipe flow\nfeature_dims_fluid = Dict{Symbol,Vector{Float16}}(\n    :x1 => Float16[0, 0, 0, 0, 0, 0, 0],     # Friction Factor\n    :x2 => Float16[1, -3, 0, 0, 0, 0, 0],    # ρ (density)  \n    :x3 => Float16[0, 1, -1, 0, 0, 0, 0],    # v (velocity) \n    :x4 => Float16[0, 1, 0, 0, 0, 0, 0],     # L (length)  \n    :x5 => Float16[0, 1, 0, 0, 0, 0, 0]      # D (diameter)\n)\ntarget_dim_fluid = Float16[1, -1, -2, 0, 0, 0, 0]    # ΔP (pressure drop) [kg m⁻¹ s⁻²]\n\n# Heat transfer: heat flux q = h⋅ΔT\nfeature_dims_heat_flux = Dict{Symbol,Vector{Float16}}(\n    :x1 => Float16[1, 0, -3, -1, 0, 0, 0],   # h (heat transfer coefficient) [W m⁻² K⁻¹]\n    :x2 => Float16[0, 0, 0, 1, 0, 0, 0],     # ΔT (temperature difference) [K]\n)\ntarget_dim_heat_flux = Float16[1, 0, -3, 0, 0, 0, 0] # q [W m⁻²]\n\n# Electromagnetism: wave propagation\nfeature_dims_em = Dict{Symbol,Vector{Float16}}(\n    :x1 => Float16[0, 1, -1, 0, 0, 0, 0],    # c (speed of light) \n    :x2 => Float16[0, 0, -1, 0, 0, 0, 0],    # f (frequency)\n    :x3 => Float16[0, 1, 0, 0, 0, 0, 0],     # λ (wavelength)\n    :x4 => Float16[-1, -3, 4, 0, 0, 2, 0],   # ε₀ (permittivity)\n    :x5 => Float16[1, 1, -2, 0, 0, -2, 0],   # μ₀ (permeability)\n)\ntarget_dim_em = Float16[0, 1, -1, 0, 0, 0, 0]        # speed [m s⁻¹]\n\nWhere the physics involves dimensionless groups, such as the Reynolds number, they can enter as derived, dimensionless features.\n\n\n\nNext: Tensor Regression"},{"title":"Coefficient Tuning Against an Expensive Loss","page":"Coefficient Tuning","location":"examples/coefficient-tuning.html#Coefficient-Tuning-Against-an-Expensive-Loss","category":"section","text":"With a CFD simulation as the cost function, every trial value of the constants of a model costs a simulation. A ScreenedNelderMead tunes them with few loss calls, inside a search or on their own, in one of three ways:\n\nNelder-Mead (screen = false): the steps of Optim.NelderMead().\nScreened Nelder-Mead (the default): a Gaussian process over the constants, fitted on the scored ones near the best, places every loss call at the minimum of its optimistic bound mean - kappa * deviation inside a trust region around the best constants. The region grows after improvements and shrinks after failures; once it is small, Nelder-Mead finishes on the loss.\nScreened swarm (swarm_box): a particle swarm explores a box first, one loss call per iteration at the position a Gaussian process ranks best, and the screened Nelder-Mead finishes once the swarm stalls.\n\nThe best constants are always ones the loss scored."},{"title":"Which One to Use","page":"Coefficient Tuning","location":"examples/coefficient-tuning.html#Which-One-to-Use","category":"section","text":"the loss use measured\nsmooth, and Nelder-Mead needs many steps ScreenedNelderMead() 1 % of the initial error after 14 to 35 loss calls on Lotka-Volterra calibrations of 2 to 4 coefficients, against 22 to 66 for Nelder-Mead; on quadratics in 5 to 8 constants after 53 to 102, where Nelder-Mead needed 107 or more than 150\neasy, or a narrow, curved valley ScreenedNelderMead(screen=false) Nelder-Mead converging further within the same calls: 0.01 % of the initial error after 32 calls on logistic growth (screened: 46), 49 on Rosenbrock (108), 78 on a quadratic of condition 100 (111); the fictive CFD closure calibration below\nseveral minima in a known range ScreenedNelderMead(swarm_box=(lower, upper)) an oscillator whose loss has minima 12 % apart: 1 % after 50 calls, against 94 (Nelder-Mead) and 98 (screened), and the global minimum from all 8 starts, the screened Nelder-Mead from 6; on smooth losses, 1.2 to 3.4 times the calls of the screened Nelder-Mead\n\nThe numbers are medians over 8 starts with 150 loss calls (benchmark/screened_constants.jl, benchmark/swarm_variants.jl). Taken apart, the screening is what makes a swarm affordable (a swarm that scores every particle reached 1 % on 4 of the 13 problems, the screened one on 6), and the Nelder-Mead after it is what makes it converge. Skipping the trial points of Nelder-Mead that a process deems hopeless, the obvious alternative, saved no loss calls: those points lie outside the simplex, where the process knows least. The process costs milliseconds per loss call."},{"title":"Inside a Search","page":"Coefficient Tuning","location":"examples/coefficient-tuning.html#Inside-a-Search","category":"section","text":"fit!(regressor, epochs, population_size, loss;\n    constant_optimizer=ScreenedNelderMead(max_evaluations=30),   # loss calls per tuning\n    optimization_epochs=5)\n\nEvery optimization_epochs epochs, if the best model has improved, its constants are tuned against the loss. One value per occurrence of a constant in the karva string is kept in the chromosome's optimised_constants, and the loss sees them only through an evaluation that applies them: elem(ctx), split_predict(elem, ctx, k) or, for a GepTensorRegressor, predictT(regressor, elem) (not elem.expression_raw, the karva string alone); equation_string and split_equations print them. Several objectives are tuned by their mean, the order of the population. With a surrogate, only a model the loss has scored is tuned. Since every model has constants of its own, a swarm takes a box relative to them: swarm_box = r spans r initial steps around each constant, about ±50 % of it for r = 1."},{"title":"On Their Own","page":"Coefficient Tuning","location":"examples/coefficient-tuning.html#On-Their-Own","category":"section","text":"# the constants of one model: kept if they beat the ones it holds\nresult = optimize_constants!(model, loss; method=ScreenedNelderMead(max_evaluations=80))\nmodel.optimised_constants, model.fitness\n\n# any function of a vector, e.g. the coefficients of a closure in a simulation\nresult = simplex_search(p -> simulation_error(p), p0;\n    method=ScreenedNelderMead(max_evaluations=100, swarm_box=(lower, upper)))\nresult.minimizer, result.minimum, result.evaluations, result.history"},{"title":"When the Solver Diverges","page":"Coefficient Tuning","location":"examples/coefficient-tuning.html#When-the-Solver-Diverges","category":"section","text":"Give a run that diverges a large error, or Inf. The Gaussian processes see the logarithm of the loss, so a large error marks the region as bad without swamping the rest, and a failed call counts as the worst value scored, so the process learns where the solver fails. On a fictive CFD closure calibration whose solver diverges next to the minimum, the screened search converged the same with 1e3, 1e10 or Inf for a diverged run; capping the large values or ranking the losses did not help."},{"title":"Example: a Closure with Fictive CFD in the Loop","page":"Coefficient Tuning","location":"examples/coefficient-tuning.html#Example:-a-Closure-with-Fictive-CFD-in-the-Loop","category":"section","text":"examples/Main_fictive_cfd_in_the_loop.jl searches for a turbulence closure nu_t(y S u_tau nu) with a fictive CFD solver in the loop: screened, with two objectives, physical units and a loss that is not smooth. The solver is not an actual CFD run but a stand-in for one that takes milliseconds: it solves the 1D momentum balance of fully developed flow between two walls,\n\n(nu + nu_t(y S)) S = tau(y) qquad S = fracdUdy\n\nfor a channel flow (tau = u_tau^2 (1 - yh)) and a Couette flow (tau = u_tau^2) at the friction Reynolds number 550, by a damped fixed-point iteration that evaluates the closure at every iteration. A closure that makes nu + nu_t negative, not finite, or keeps the iteration from converging diverges, and the loss gives that flow the error 1e3. The reference profiles come from van Driest's mixing length.\n\nThe features carry their SI units, keyed by the names in entered_features (the regressor warns about a key that names no feature), and the search is held to the unit of nu_t:\n\nunits = Dict{Symbol,Vector{Float16}}(          # SI exponents [kg, m, s, K, mol, A, cd]\n    :y => Float16[0, 1, 0, 0, 0, 0, 0],         # wall distance, m\n    :S => Float16[0, 0, -1, 0, 0, 0, 0],        # shear rate, 1/s\n    :u_tau => Float16[0, 1, -1, 0, 0, 0, 0],    # friction velocity, m/s\n    :nu => Float16[0, 2, -1, 0, 0, 0, 0])       # viscosity, m^2/s\nregressor = GepRegressor(4; entered_features=[:y, :S, :u_tau, :nu],\n    entered_non_terminals=[:+, :-, :*, :/, :exp], considered_dimensions=units,\n    gene_count=2, head_len=6, number_of_objectives=2, rounds=4)\n\n# one objective per flow: the relative error of its velocity profile, 1e3 if it diverged;\n# the solver evaluates elem(ctx), which applies tuned constants, at every iteration\nfunction loss(elem, validate::Bool)\n    isnan(mean(elem.fitness)) || validate || return\n    local ctx = ctxs[Threads.threadid()]\n    local S = ctx.nodes[s_sym]\n    local diverged = solve!(S, () -> try elem(ctx) catch; nothing end)\n    elem.fitness = flow_errors(S, diverged)\nend\n\nfit!(regressor, 100, 400, loss;\n    surrogate=SurrogateScreening(regressor, probes; individuals_per_epoch=0.15, seed=1),\n    target_dimension=Float16[0, 2, -1, 0, 0, 0, 0], hof=10,\n    constant_optimizer=ScreenedNelderMead(max_evaluations=30), optimization_epochs=10)\n\nWith the script's seed, the same at any thread count, the search made 4,234 fictive CFD runs in 80 to 100 s on 4 threads, 1,132 of which diverged, and returned nu_t = 000675 y^2 u_tau^2nu, homogeneous in m²/s, with relative errors of 2.7e-3 (channel) and 3.7e-3 (Couette).\n\nThe script then calibrates van Driest's mixing length with a viscosity correction, nu_t = (k y D)^2 S + c nu with D = 1 - e^-y^+A, within bounds part of which diverge (c  -1), from 6 starts with 100 fictive CFD runs each. Every method found the reference constants k = 041, A = 26, c = 0; plain Nelder-Mead reached the smallest median error (1.3e-7), and the swarm solved into the diverging part 13 times without harm. This loss is one valley, where the swarm brings nothing.\n\nexamples/Main_screened_constants.jl is the smaller example: the constants of a search for an ODE tuned in the loop, and four ODE coefficients calibrated with and without screening."},{"title":"Running the Examples","page":"Coefficient Tuning","location":"examples/coefficient-tuning.html#Running-the-Examples","category":"section","text":"julia --project=. --threads=4 examples/Main_screened_constants.jl\njulia --project=. --threads=4 examples/Main_fictive_cfd_in_the_loop.jl\n\n\n\nContinue to the API Reference for every option."},{"title":"Getting Started","page":"Getting Started","location":"getting-started.html#Getting-Started","category":"section","text":"This guide runs a first symbolic regression and shows the options you are most likely to change. Core Concepts explains the algorithm behind them."},{"title":"What is Gene Expression Programming?","page":"Getting Started","location":"getting-started.html#What-is-Gene-Expression-Programming?","category":"section","text":"Gene Expression Programming (GEP) is an evolutionary algorithm that evolves mathematical expressions. A model is a fixed-length linear chromosome: genes, each a head (functions and terminals) and a tail (terminals only), joined by connectors. Each gene is read in prefix order until its expression is complete; the tail, which holds only terminals, is long enough for that. GeneExpressionProgramming.jl evaluates the expressed part of the chromosome, its karva string, directly on data columns, without building an expression tree. It adds multi-objective selection and physical-dimension constraints."},{"title":"Your First Symbolic Regression","page":"Getting Started","location":"getting-started.html#Your-First-Symbolic-Regression","category":"section","text":""},{"title":"Step 1: Load the Package","page":"Getting Started","location":"getting-started.html#Step-1:-Load-the-Package","category":"section","text":"using GeneExpressionProgramming\nusing Random\n\nStart Julia with several threads (julia --threads=auto) to evaluate the population in parallel."},{"title":"Step 2: Generate Sample Data","page":"Getting Started","location":"getting-started.html#Step-2:-Generate-Sample-Data","category":"section","text":"A synthetic dataset with a known relationship:\n\n# Set random seed for reproducibility\nRandom.seed!(42)\n\n# Define the number of features\nnumber_features = 2\n\n# Generate random input data, one row per sample\nn_samples = 100\nx_data = randn(Float64, n_samples, number_features)\n\n# Define the true function: f(x1, x2) = x1² + x1*x2 - 2*x2²\ny_data = @. x_data[:,1]^2 + x_data[:,1] * x_data[:,2] - 2 * x_data[:,2]^2\n\n# Add some noise\ny_data += 0.1 * randn(n_samples)"},{"title":"Step 3: Create the Regressor","page":"Getting Started","location":"getting-started.html#Step-3:-Create-the-Regressor","category":"section","text":"# Create a GEP regressor\nregressor = GepRegressor(number_features)\n\n# Define evolution parameters\nepochs = 1000          # Number of generations\npopulation_size = 1000 # Size of the population\n\nThe defaults are 3 genes with a head length of 6, the functions + - * / (also the connectors), and as constants 0.0, 0.5 and one random constant drawn from [0, 1). Customizing the Regressor shows how to change them."},{"title":"Step 4: Train the Model","page":"Getting Started","location":"getting-started.html#Step-4:-Train-the-Model","category":"section","text":"# Fit the regressor to the data\nfit!(regressor, epochs, population_size, x_data', y_data; loss_fun=\"mse\")\n\nfit! expects the features with one row per feature and one column per sample, hence the transpose of x_data."},{"title":"Step 5: Make Predictions and Analyze Results","page":"Getting Started","location":"getting-started.html#Step-5:-Make-Predictions-and-Analyze-Results","category":"section","text":"# Make predictions on the training data\npredictions = regressor(x_data')\n\n# Display the best evolved expression\nprintln(\"Best expression: \", regressor.best_models_[1])\nprintln(\"Fitness (MSE): \", regressor.best_models_[1].fitness[1])\n\n# R² with the package's score\nr2 = get_loss_function(\"r2_score\")(y_data, predictions)\nprintln(\"R² Score: \", r2)"},{"title":"Step 6: Visualize Results (Optional)","page":"Getting Started","location":"getting-started.html#Step-6:-Visualize-Results-(Optional)","category":"section","text":"Plots.jl is not a dependency of the package; install it into your environment (Pkg.add(\"Plots\")) to draw the results.\n\nusing Plots\n\n# Create a scatter plot comparing actual vs predicted values\nscatter(y_data, predictions, \n        xlabel=\"Actual Values\", \n        ylabel=\"Predicted Values\",\n        title=\"Actual vs Predicted Values\",\n        label=\"Predictions\",\n        alpha=0.6)\n\n# Add perfect prediction line\nplot!([minimum(y_data), maximum(y_data)], \n      [minimum(y_data), maximum(y_data)], \n      color=:red, \n      linestyle=:dash,\n      label=\"Perfect Prediction\")"},{"title":"Understanding the Results","page":"Getting Started","location":"getting-started.html#Understanding-the-Results","category":"section","text":"regressor.best_models_ holds the hof best models of the run (3 by default), best first; regressor(x) predicts with the first.\nA model's fitness is a tuple with one entry per objective, here the training MSE (lower is better). A model whose karva string repeats another's carries that fitness times the duplicate penalty (see Population Dynamics).\nThe R² score is the coefficient of determination (closer to 1 is better)."},{"title":"Interpreting Evolved Expressions","page":"Getting Started","location":"getting-started.html#Interpreting-Evolved-Expressions","category":"section","text":"Printing a model writes it as an equation:\n\nx1, x2, etc. are the input features (or the names given in entered_features)\nEvery binary operation is parenthesised, so the printed form is unambiguous\nOther functions appear in mathematical notation if they are in the function set: sin(…), e^(…) for exp, ln(…) for log, √(…), (…)² for sqr, |…| for abs\n\nFor example, an evolved expression might look like:\n\n((x1 * x1) + (x2 * (x1 - (x2 + x2))))\n\nwhich is x1² + x1·x2 − 2·x2², the original function, though not in its simplest form. When the constant optimiser has tuned the constants of a model, they are printed with their fitted values (regressor.best_models_[1].optimised_constants holds them)."},{"title":"Working with Real Data","page":"Getting Started","location":"getting-started.html#Working-with-Real-Data","category":"section","text":""},{"title":"Loading Data from Files","page":"Getting Started","location":"getting-started.html#Loading-Data-from-Files","category":"section","text":"using CSV, DataFrames\n\n# Load data from CSV\ndf = CSV.read(\"your_data.csv\", DataFrame)                # your file\n\n# Extract features and target\nfeature_columns = [:feature1, :feature2, :feature3]      # your column names\ntarget_column = :target\n\nx_data = Matrix{Float64}(df[:, feature_columns])         # one row per sample\ny_data = Float64.(df[:, target_column])\n\n# Get number of features\nnumber_features = length(feature_columns)\n\nFeatures and target should share one floating-point type, as train_test_split requires."},{"title":"Data Preprocessing","page":"Getting Started","location":"getting-started.html#Data-Preprocessing","category":"section","text":"minmax_scale maps each column onto the interval from 0 to 1, or the one feature_range sets; the evolved expressions are then in the scaled variables.\n\nx_data_scaled = minmax_scale(x_data)"},{"title":"Train-Test Split","page":"Getting Started","location":"getting-started.html#Train-Test-Split","category":"section","text":"The package exports train_test_split, which shuffles the rows (one sample per row) and splits them at train_ratio:\n\nx_train, y_train, x_test, y_test = train_test_split(x_data, y_data; train_ratio=0.8)\n\n# the held-out set is the validation data reported during training\nfit!(regressor, epochs, population_size, x_train', y_train;\n     x_test=x_test', y_test=y_test, loss_fun=\"mse\")\n\nconsider=k keeps every k-th row of both parts, to subsample large files."},{"title":"Customizing the Regressor","page":"Getting Started","location":"getting-started.html#Customizing-the-Regressor","category":"section","text":""},{"title":"Basic Parameters","page":"Getting Started","location":"getting-started.html#Basic-Parameters","category":"section","text":"regressor = GepRegressor(\n    number_features;\n    gene_count = 2,                     # Number of genes per chromosome (default 3)\n    head_len = 7,                       # Head length of genes (default 6)\n    rnd_count = 2,                      # Number of random constants (default 1)\n    tail_weigths = [0.6, 0.2, 0.2],     # Sampling weight of each feature, fixed constant and random constant\n    gene_connections = [:+, :-, :*, :/], # Connectors; only those also among the functions are used\n    entered_terminal_nums = [Symbol(0.0), Symbol(0.5)] # Constant terminals\n)"},{"title":"Function Set Customization","page":"Getting Started","location":"getting-started.html#Function-Set-Customization","category":"section","text":"# Define custom function set\ncustom_functions = [\n    :+, :-, :*, :/,              # Basic arithmetic\n    :sin, :cos, :exp, :log,      # Transcendental functions\n    :sqrt, :abs                  # Other functions\n]\n\nregressor = GepRegressor(number_features; entered_non_terminals=custom_functions)\n\nFunction Sets lists every available function. A candidate that cannot be evaluated, e.g. the log of a negative number, gets the worst fitness (Inf)."},{"title":"Loss Function Options","page":"Getting Started","location":"getting-started.html#Loss-Function-Options","category":"section","text":"# Mean Squared Error (default)\nfit!(regressor, epochs, population_size, x_train', y_train; loss_fun=\"mse\")\n\n# Mean Absolute Error\nfit!(regressor, epochs, population_size, x_train', y_train; loss_fun=\"mae\")\n\n# Root Mean Squared Error\nfit!(regressor, epochs, population_size, x_train', y_train; loss_fun=\"rmse\")\n\n# Any function of (y_true, y_pred) that returns a number to minimise\nfit!(regressor, epochs, population_size, x_train', y_train;\n     loss_fun=(y, p) -> maximum(abs.(y .- p)))\n\nThe named losses are \"mse\", \"rmse\", \"mae\", \"nrmse\", \"srsme\", \"r2_score\", \"r2_score_f\" and \"xi_core\" (see Loss Functions); the search minimises, so use the error measures to drive it and the scores to report on it."},{"title":"Monitoring Training Progress","page":"Getting Started","location":"getting-started.html#Monitoring-Training-Progress","category":"section","text":"# After training: one tuple per epoch; epochs after a break condition stopped the run are unassigned\ntrain_loss = regressor.fitness_history_.train_loss\nfitness_history = [train_loss[i][1] for i in eachindex(train_loss) if isassigned(train_loss, i)]\n\n# Plot fitness over generations (Plots.jl)\nplot(1:length(fitness_history), fitness_history,\n     xlabel=\"Generation\",\n     ylabel=\"Fitness (MSE)\",\n     title=\"Training Progress\",\n     legend=false)"},{"title":"Tuning","page":"Getting Started","location":"getting-started.html#Tuning","category":"section","text":"Search effort: population_size and epochs (arguments of fit!); a break_condition=(population, epoch) -> Bool stops a run early when it returns true (see Early Stopping).\nExpression size: head_len and gene_count bound it; to trade accuracy against size explicitly, use several objectives.\nGenetic operators: their rates are in RegressionWrapper.GENE_COMMON_PROBS (see Genetic Operators).\nCoefficients: linear_scaling=true solves one least-squares coefficient per gene, so evolution only searches for the structure (needs :+ and :* among the functions).\nThreads: start Julia with more threads (julia --threads=auto)."},{"title":"Next Steps","page":"Getting Started","location":"getting-started.html#Next-Steps","category":"section","text":"Multi-Objective Optimization: Balance accuracy and complexity\nPhysical Dimensionality: Ensure dimensional consistency\nTensor Regression: Work with vector and matrix data\nSurrogate Screening: Search with an expensive loss, such as a solver in the loop\n\n\n\nContinue to Core Concepts for the algorithm behind these options."}]
}
